  const subtitle = `RELATÓRIO GERAL E FINANCEIRO - ${periodLabel.toUpperCase()}`;

  drawPageOneHeader(doc, subtitle, dataEmissao, horaEmissao, company);

  // Financial summary box (Y=38 to Y=72)
