import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, MapPin, Flag, Tag, Car, PlusCircle, CheckCircle, AlertCircle, Sparkles, ArrowDownRight, Database, X } from 'lucide-react';
import { Driver, Passenger } from '../types';

interface PassengerFormProps {
  drivers: Driver[];
  passengers?: Passenger[];
  onSavePassenger: (passenger: Passenger) => void;
  onOpenDriverModal: () => void;
  editingPassenger?: Passenger | null;
  onCancelEdit?: () => void;
}

export const PassengerForm: React.FC<PassengerFormProps> = ({
  drivers,
  passengers = [],
  onSavePassenger,
  onOpenDriverModal,
  editingPassenger,
  onCancelEdit,
}) => {
  const [fullName, setFullName] = useState('');
  const [origin, setOrigin] = useState('');
  const [destination, setDestination] = useState('');
  const [seller, setSeller] = useState('');
  const [driverId, setDriverId] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [autoPulledNotice, setAutoPulledNotice] = useState<string | null>(null);
  const [isSuggestionsOpen, setIsSuggestionsOpen] = useState(false);
  const suggestionsRef = useRef<HTMLDivElement>(null);

  // Close suggestions when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (suggestionsRef.current && !suggestionsRef.current.contains(e.target as Node)) {
        setIsSuggestionsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Filter existing passengers in database matching the typed name
  const matchedPassengers = useMemo(() => {
    const query = fullName.trim().toLowerCase();
    if (!query || query.length < 2 || editingPassenger) return [];
    return passengers.filter((p) => p.fullName.toLowerCase().includes(query)).slice(0, 5);
  }, [fullName, passengers, editingPassenger]);

  // Exact match detection
  const exactMatchPassenger = useMemo(() => {
    const query = fullName.trim().toLowerCase();
    if (!query || query.length < 3 || editingPassenger) return null;
    return passengers.find((p) => p.fullName.trim().toLowerCase() === query) || null;
  }, [fullName, passengers, editingPassenger]);

  // Handle auto-pulling data from an existing passenger in the database
  const handleAutoPullPassenger = (p: Passenger) => {
    setFullName(p.fullName);
    setOrigin(p.origin);
    setDestination(p.destination);
    setSeller(p.seller);
    if (p.driverId) {
      setDriverId(p.driverId);
    }
    setIsSuggestionsOpen(false);
    setAutoPulledNotice(`Cliente "${p.fullName}" já cadastrado na base! Os dados de rota e vendedor foram preenchidos automaticamente.`);
  };

  // Populate form if editing
  useEffect(() => {
    if (editingPassenger) {
      setFullName(editingPassenger.fullName);
      setOrigin(editingPassenger.origin);
      setDestination(editingPassenger.destination);
      setSeller(editingPassenger.seller);
      setDriverId(editingPassenger.driverId || '');
    } else {
      setFullName('');
      setOrigin('');
      setDestination('');
      setSeller('');
      setDriverId('');
    }
  }, [editingPassenger]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const trimmedName = fullName.trim();
    const trimmedOrigin = origin.trim();
    const trimmedDestination = destination.trim();
    const trimmedSeller = seller.trim();

    if (!trimmedName) {
      setError('Informe o nome completo do cliente / passageiro.');
      return;
    }
    if (!trimmedOrigin) {
      setError('Informe a origem da viagem.');
      return;
    }
    if (!trimmedDestination) {
      setError('Informe o destino da viagem.');
      return;
    }
    if (!trimmedSeller) {
      setError('Informe o vendedor da passagem.');
      return;
    }

    const passengerData: Passenger = {
      id: editingPassenger ? editingPassenger.id : `pass-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      fullName: trimmedName.toUpperCase(),
      origin: trimmedOrigin.toUpperCase(),
      destination: trimmedDestination.toUpperCase(),
      seller: trimmedSeller.toUpperCase(),
      driverId: driverId || '',
      createdAt: editingPassenger ? editingPassenger.createdAt : new Date().toISOString(),
    };

    onSavePassenger(passengerData);

    setSuccess(
      editingPassenger
        ? 'Passageiro atualizado com sucesso!'
        : driverId
        ? 'Passageiro cadastrado e destinado ao motorista!'
        : 'Passageiro salvo na Lista Geral! Você pode alocar o motorista na lista.'
    );

    if (!editingPassenger) {
      setFullName('');
      setOrigin('');
      setDestination('');
      setSeller('');
      setDriverId('');
    }

    setTimeout(() => {
      setSuccess('');
      if (editingPassenger && onCancelEdit) {
        onCancelEdit();
      }
    }, 1200);
  };

  return (
    <div id="passenger-form-container" className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden mb-4">
      <div className="bg-slate-900 px-5 py-3.5 text-white flex items-center justify-between">
        <div className="flex items-center space-x-2.5">
          <div className="p-1.5 bg-slate-800 rounded-lg text-emerald-400">
            <User className="w-5 h-5" />
          </div>
          <div>
            <h2 className="font-bold text-sm sm:text-base leading-tight">
              {editingPassenger ? 'Editar Passageiro' : 'Cadastro de Cliente Passageiro'}
            </h2>
            <p className="text-[11px] text-slate-400">
              {editingPassenger ? 'Atualize as informações da viagem' : 'Preencha os dados e destine o motorista'}
            </p>
          </div>
        </div>

        {editingPassenger && onCancelEdit && (
          <button
            type="button"
            onClick={onCancelEdit}
            className="text-xs bg-slate-800 hover:bg-slate-700 text-slate-300 px-2.5 py-1 rounded-md transition"
          >
            Cancelar
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-4 sm:p-5 space-y-4">
        {error && (
          <div
            id="passenger-form-error"
            className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-rose-700 text-xs font-medium flex items-start gap-2"
          >
            <AlertCircle className="w-4 h-4 text-rose-500 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {success && (
          <div
            id="passenger-form-success"
            className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-emerald-700 text-xs font-medium flex items-center gap-2"
          >
            <CheckCircle className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>{success}</span>
          </div>
        )}

        {/* Auto Pulled from Database Notice */}
        {autoPulledNotice && (
          <div className="p-3 bg-emerald-50 border border-emerald-300 rounded-xl text-emerald-900 text-xs font-medium flex items-center justify-between gap-2 animate-in fade-in duration-150">
            <div className="flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-emerald-600 shrink-0" />
              <span>{autoPulledNotice}</span>
            </div>
            <button
              type="button"
              onClick={() => setAutoPulledNotice(null)}
              className="text-emerald-700 hover:text-emerald-900 p-1 cursor-pointer"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* 1. Nome Completo com Busca Flutuante e Detecção de Base */}
        <div className="relative" ref={suggestionsRef}>
          <div className="flex items-center justify-between mb-1.5">
            <label
              htmlFor="passenger-fullname-input"
              className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-700"
            >
              <User className="w-3.5 h-3.5 text-slate-500" />
              <span>Nome Completo do Passageiro *</span>
            </label>
            {!editingPassenger && (
              <span className="text-[11px] text-slate-400 flex items-center gap-1">
                <Database className="w-3 h-3 text-emerald-600" />
                <span>Busca automática na base</span>
              </span>
            )}
          </div>

          <div className="relative">
            <input
              id="passenger-fullname-input"
              type="text"
              value={fullName}
              onFocus={() => setIsSuggestionsOpen(true)}
              onChange={(e) => {
                setFullName(e.target.value);
                setIsSuggestionsOpen(true);
                setAutoPulledNotice(null);
              }}
              placeholder="Ex: Carlos Eduardo de Oliveira"
              className="w-full px-3.5 py-2.5 text-sm bg-slate-50 border border-slate-300 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition text-slate-900 placeholder-slate-400"
              autoComplete="off"
            />
            {fullName && (
              <button
                type="button"
                onClick={() => {
                  setFullName('');
                  setIsSuggestionsOpen(false);
                  setAutoPulledNotice(null);
                }}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1 cursor-pointer"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>

          {/* BARRA DE BUSCA FLUTUANTE (DROPDOWN AUTOCOMPLETE) */}
          {isSuggestionsOpen && matchedPassengers.length > 0 && (
            <div className="absolute left-0 right-0 top-full mt-1.5 z-40 bg-white border border-emerald-200 rounded-xl shadow-xl overflow-hidden divide-y divide-slate-100 animate-in fade-in slide-in-from-top-1 duration-150">
              <div className="px-3 py-2 bg-emerald-50/80 border-b border-emerald-100 flex items-center justify-between text-[11px] text-emerald-900 font-bold">
                <span className="flex items-center gap-1.5">
                  <Sparkles className="w-3.5 h-3.5 text-emerald-700" />
                  Cliente(s) já encontrado(s) na base de dados:
                </span>
                <span className="text-emerald-700 text-[10px] font-normal">
                  Clique para puxar dados
                </span>
              </div>

              <div className="max-h-56 overflow-y-auto">
                {matchedPassengers.map((match) => (
                  <div
                    key={match.id}
                    onClick={() => handleAutoPullPassenger(match)}
                    className="p-3 hover:bg-emerald-50/50 cursor-pointer transition flex items-center justify-between gap-2 group"
                  >
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="text-xs font-bold text-slate-900 group-hover:text-emerald-700 transition truncate">
                          {match.fullName}
                        </p>
                        <span className="px-1.5 py-0.5 bg-slate-100 text-slate-600 rounded text-[10px] font-medium shrink-0">
                          Na base
                        </span>
                      </div>
                      <p className="text-[11px] text-slate-500 truncate mt-0.5">
                        <span className="text-emerald-700 font-medium">{match.origin}</span> → <span className="text-rose-600 font-medium">{match.destination}</span>
                        {match.seller && <span className="text-slate-400"> • Vend: {match.seller}</span>}
                      </p>
                    </div>

                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleAutoPullPassenger(match);
                      }}
                      className="px-2.5 py-1.5 bg-emerald-700 hover:bg-emerald-800 text-white rounded-lg text-[11px] font-bold shrink-0 transition active:scale-95 cursor-pointer inline-flex items-center gap-1 shadow-xs"
                    >
                      <ArrowDownRight className="w-3.5 h-3.5" />
                      <span>Puxar Dados</span>
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Quick Exact Match Callout */}
          {exactMatchPassenger && !autoPulledNotice && (
            <div className="mt-2 bg-amber-50 border border-amber-200 rounded-xl p-2.5 flex items-center justify-between gap-2 text-xs text-amber-900">
              <div className="flex items-center gap-1.5">
                <AlertCircle className="w-4 h-4 text-amber-600 shrink-0" />
                <span>
                  <strong>Atenção:</strong> "{exactMatchPassenger.fullName}" já está cadastrado na base!
                </span>
              </div>
              <button
                type="button"
                onClick={() => handleAutoPullPassenger(exactMatchPassenger)}
                className="px-2.5 py-1 bg-amber-700 hover:bg-amber-800 text-white rounded-lg text-[11px] font-bold shrink-0 transition cursor-pointer"
              >
                Puxar Dados Automaticamente
              </button>
            </div>
          )}
        </div>

        {/* 2. Campos Separados: Cidade de Origem e Cidade de Destino */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div className="p-3 bg-emerald-50/30 rounded-xl border-2 border-emerald-200">
            <label
              htmlFor="passenger-origin-input"
              className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-emerald-950 mb-1.5"
            >
              <MapPin className="w-4 h-4 text-emerald-700" />
              <span>Cidade de Origem *</span>
            </label>
            <input
              id="passenger-origin-input"
              type="text"
              value={origin}
              onChange={(e) => setOrigin(e.target.value)}
              placeholder="Ex: São Paulo - SP"
              className="w-full px-3.5 py-2.5 text-sm bg-white border-2 border-slate-300 rounded-xl focus:outline-none focus:border-emerald-600 transition text-slate-900 font-semibold placeholder-slate-400"
            />
          </div>

          <div className="p-3 bg-rose-50/30 rounded-xl border-2 border-rose-200">
            <label
              htmlFor="passenger-destination-input"
              className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider text-rose-950 mb-1.5"
            >
              <Flag className="w-4 h-4 text-rose-600" />
              <span>Cidade de Destino *</span>
            </label>
            <input
              id="passenger-destination-input"
              type="text"
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              placeholder="Ex: Belo Horizonte - MG"
              className="w-full px-3.5 py-2.5 text-sm bg-white border-2 border-slate-300 rounded-xl focus:outline-none focus:border-rose-600 transition text-slate-900 font-semibold placeholder-slate-400"
            />
          </div>
        </div>

        {/* 3. Vendedor da Passagem */}
        <div>
          <label
            htmlFor="passenger-seller-input"
            className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-700 mb-1.5"
          >
            <Tag className="w-3.5 h-3.5 text-amber-600" />
            <span>Vendedor da Passagem *</span>
          </label>
          <input
            id="passenger-seller-input"
            type="text"
            value={seller}
            onChange={(e) => setSeller(e.target.value)}
            placeholder="Ex: Maria Vendedora / Guichê Central / Agência 01"
            className="w-full px-3.5 py-2.5 text-sm bg-slate-50 border border-slate-300 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition text-slate-900 placeholder-slate-400"
          />
        </div>

          {/* 4. Destinar para qual motorista ele irá viajar (opcional no cadastro, alocável a qualquer momento na Lista Geral) */}
        <div className="pt-2 border-t border-slate-100">
          <div className="flex items-center justify-between mb-1.5">
            <label
              htmlFor="passenger-driver-select"
              className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-slate-700"
            >
              <Car className="w-3.5 h-3.5 text-emerald-600" />
              <span>Motorista da Viagem (Alocação)</span>
            </label>
            <button
              id="passenger-form-quick-add-driver-btn"
              type="button"
              onClick={onOpenDriverModal}
              className="text-[11px] font-semibold text-emerald-700 hover:text-emerald-800 inline-flex items-center gap-1 hover:underline cursor-pointer"
            >
              <PlusCircle className="w-3.5 h-3.5" />
              <span>Novo Motorista</span>
            </button>
          </div>

          {drivers.length === 0 ? (
            <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs text-amber-800 flex items-center justify-between">
              <span>Nenhum motorista cadastrado ainda. O passageiro será salvo na Lista Geral.</span>
              <button
                type="button"
                onClick={onOpenDriverModal}
                className="px-2.5 py-1 bg-amber-600 hover:bg-amber-700 text-white font-medium rounded-lg text-xs transition cursor-pointer"
              >
                Cadastrar Agora
              </button>
            </div>
          ) : (
            <div className="relative">
              <select
                id="passenger-driver-select"
                value={driverId}
                onChange={(e) => setDriverId(e.target.value)}
                className="w-full px-3.5 py-2.5 text-sm bg-slate-50 border border-slate-300 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition text-slate-900 font-medium appearance-none cursor-pointer"
              >
                <option value="">
                  Deixar sem motorista (Alocar depois pela Lista Geral)
                </option>
                {drivers.map((drv) => (
                  <option key={drv.id} value={drv.id}>
                    Alocar para: {drv.fullName}
                  </option>
                ))}
              </select>
              <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-3.5 text-slate-500">
                <svg className="w-4 h-4 fill-current" viewBox="0 0 20 20">
                  <path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" />
                </svg>
              </div>
            </div>
          )}
          <p className="text-[11px] text-slate-500 mt-1">
            Você pode alocar o motorista agora ou diretamente na Lista Geral de Passageiros.
          </p>
        </div>

        {/* Action button */}
        <div className="pt-2">
          <button
            id="passenger-form-submit-btn"
            type="submit"
            className="w-full py-3 px-4 bg-emerald-600 hover:bg-emerald-700 active:scale-[0.99] text-white font-semibold text-sm rounded-xl shadow-md transition flex items-center justify-center gap-2 cursor-pointer"
          >
            <CheckCircle className="w-4 h-4" />
            <span>{editingPassenger ? 'Salvar Alterações' : 'Cadastrar e Destinar Passageiro'}</span>
          </button>
        </div>
      </form>
    </div>
  );
};

src/components/PassengerRow.tsx:
import React, { useState } from 'react';
import {
  MapPin,
  Flag,
  ArrowRight,
  Tag,
  Car,
  Trash2,
  Edit3,
  Share2,
  Check,
  X,
  CalendarDays,
  Plus,
} from 'lucide-react';
import { Passenger, Driver } from '../types';

interface PassengerRowProps {
  index: number;
  passenger: Passenger;
  driver?: Driver;
  drivers: Driver[];
  onEdit: (passenger: Passenger) => void;
  onDelete: (id: string) => void;
  onQuickAllocateDriver: (passengerId: string, driverId: string) => void;
  onUpdateOrigin?: (passengerId: string, newOrigin: string) => void;
  onUpdateDestination: (passengerId: string, newDestination: string) => void;
  onUpdateSeller?: (passengerId: string, newSeller: string) => void;
  onAddToDailyList?: (passengerId: string) => void;
  isInDailyList?: boolean;
}

export const PassengerRow: React.FC<PassengerRowProps> = ({
  index,
  passenger,
  driver,
  drivers,
  onEdit,
  onDelete,
  onQuickAllocateDriver,
  onUpdateOrigin,
  onUpdateDestination,
  onUpdateSeller,
  onAddToDailyList,
  isInDailyList = false,
}) => {
  // Inline edit state for origin
  const [isEditingOrigin, setIsEditingOrigin] = useState(false);
  const [originInput, setOriginInput] = useState(passenger.origin);

  // Inline edit state for destination
  const [isEditingDestination, setIsEditingDestination] = useState(false);
  const [destinationInput, setDestinationInput] = useState(passenger.destination);

  // Inline edit state for seller
  const [isEditingSeller, setIsEditingSeller] = useState(false);
  const [sellerInput, setSellerInput] = useState(passenger.seller);

  const handleShareWhatsApp = () => {
    const text = `*COMPROVANTE DE EMBARQUE - TRANSPORTE*\n👤 *Passageiro:* ${passenger.fullName}\n📍 *Origem:* ${passenger.origin}\n🏁 *Destino:* ${passenger.destination}\n🏷️ *Vendedor:* ${passenger.seller}\n🚐 *Motorista:* ${driver ? driver.fullName : 'Não informado'}`;
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleSaveOrigin = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = originInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.origin && onUpdateOrigin) {
      onUpdateOrigin(passenger.id, trimmed);
    }
    setIsEditingOrigin(false);
  };

  const handleSaveDestination = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = destinationInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.destination) {
      onUpdateDestination(passenger.id, trimmed);
    }
    setIsEditingDestination(false);
  };

  const handleSaveSeller = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = sellerInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.seller && onUpdateSeller) {
      onUpdateSeller(passenger.id, trimmed);
    }
    setIsEditingSeller(false);
  };

  return (
    <div
      id={`passenger-row-${passenger.id}`}
      className={`group bg-white hover:bg-emerald-50/25 border-2 transition-all duration-150 rounded-xl px-3 py-2.5 sm:py-2 text-xs flex flex-wrap lg:flex-nowrap items-center justify-between gap-2.5 sm:gap-3.5 shadow-2xs hover:shadow-xs hover:border-emerald-500 ${
        driver ? 'border-slate-300' : 'border-amber-400 bg-amber-50/25'
      }`}
    >
      {/* Col 1: Index + Client Name */}
      <div className="flex items-center space-x-2.5 min-w-[200px] max-w-xs xl:max-w-sm flex-1">
        <span
          className={`w-6 h-6 rounded-lg text-[11px] font-bold flex items-center justify-center shrink-0 border-2 ${
            driver
              ? 'bg-emerald-50 text-emerald-800 border-emerald-300'
              : 'bg-amber-100 text-amber-900 border-amber-400'
          }`}
          title={driver ? `Motorista: ${driver.fullName}` : 'Aguardando Motorista'}
        >
          {index}
        </span>

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            <h4
              className="font-bold text-slate-900 truncate text-xs sm:text-[13px] leading-tight"
              title={passenger.fullName}
            >
              {passenger.fullName}
            </h4>
            {!driver && (
              <span
                className="w-2 h-2 rounded-full bg-amber-500 shrink-0"
                title="Sem motorista alocado"
              />
            )}
          </div>
        </div>
      </div>

      {/* Campo 1: Cidade de Origem */}
      <div className="flex items-center gap-1.5 shrink-0 bg-emerald-50/50 border-2 border-emerald-300/80 px-2.5 py-1 rounded-lg text-[11px] shadow-2xs">
        <MapPin className="w-3.5 h-3.5 text-emerald-700 shrink-0" />
        <span className="text-[10px] font-extrabold text-emerald-800 uppercase tracking-tight">Origem:</span>

        {isEditingOrigin ? (
          <form onSubmit={handleSaveOrigin} className="flex items-center gap-1">
            <input
              type="text"
              value={originInput}
              onChange={(e) => setOriginInput(e.target.value.toUpperCase())}
              placeholder="Cidade de Origem..."
              autoFocus
              className="text-[11px] px-1.5 py-0.5 bg-white border-2 border-emerald-500 rounded font-semibold text-slate-900 focus:outline-none w-28 uppercase"
            />
            <button
              type="submit"
              className="p-0.5 bg-emerald-600 text-white rounded hover:bg-emerald-700 cursor-pointer"
              title="Salvar Origem"
            >
              <Check className="w-3 h-3" />
            </button>
            <button
              type="button"
              onClick={() => {
                setOriginInput(passenger.origin);
                setIsEditingOrigin(false);
              }}
              className="p-0.5 bg-slate-200 text-slate-600 rounded hover:bg-slate-300 cursor-pointer"
              title="Cancelar"
            >
              <X className="w-3 h-3" />
            </button>
          </form>
        ) : (
          <button
            type="button"
            onClick={() => {
              setOriginInput(passenger.origin);
              setIsEditingOrigin(true);
            }}
            className="font-bold text-slate-800 max-w-[110px] truncate hover:underline hover:text-emerald-800 cursor-pointer flex items-center gap-1"
            title="Clique para alterar a cidade de origem"
          >
            <span className="truncate">{passenger.origin}</span>
            <Edit3 className="w-2.5 h-2.5 text-emerald-600/70 hover:text-emerald-800 shrink-0" />
          </button>
        )}
      </div>

      {/* Campo 2: Cidade de Destino */}
      <div className="flex items-center gap-1.5 shrink-0 bg-rose-50/50 border-2 border-rose-300/80 px-2.5 py-1 rounded-lg text-[11px] shadow-2xs">
        <Flag className="w-3.5 h-3.5 text-rose-600 shrink-0" />
        <span className="text-[10px] font-extrabold text-rose-800 uppercase tracking-tight">Destino:</span>

        {isEditingDestination ? (
          <form onSubmit={handleSaveDestination} className="flex items-center gap-1">
            <input
              type="text"
              value={destinationInput}
              onChange={(e) => setDestinationInput(e.target.value.toUpperCase())}
              placeholder="Cidade de Destino..."
              autoFocus
              className="text-[11px] px-1.5 py-0.5 bg-white border-2 border-rose-500 rounded font-semibold text-slate-900 focus:outline-none w-28 uppercase"
            />
            <button
              type="submit"
              className="p-0.5 bg-rose-600 text-white rounded hover:bg-rose-700 cursor-pointer"
              title="Salvar Destino"
            >
              <Check className="w-3 h-3" />
            </button>
            <button
              type="button"
              onClick={() => {
                setDestinationInput(passenger.destination);
                setIsEditingDestination(false);
              }}
              className="p-0.5 bg-slate-200 text-slate-600 rounded hover:bg-slate-300 cursor-pointer"
              title="Cancelar"
            >
              <X className="w-3 h-3" />
            </button>
          </form>
        ) : (
          <button
            type="button"
            onClick={() => {
              setDestinationInput(passenger.destination);
              setIsEditingDestination(true);
            }}
            className="font-bold text-rose-950 max-w-[120px] truncate hover:underline hover:text-rose-700 cursor-pointer flex items-center gap-1"
            title="Clique para alterar a cidade de destino"
          >
            <span className="truncate">{passenger.destination}</span>
            <Edit3 className="w-2.5 h-2.5 text-rose-500/70 hover:text-rose-700 shrink-0" />
          </button>
        )}
      </div>

      {/* Col 3: Seller Badge with inline quick edit */}
      <div className="shrink-0">
        {isEditingSeller ? (
          <form onSubmit={handleSaveSeller} className="flex items-center gap-1">
            <input
              type="text"
              value={sellerInput}
              onChange={(e) => setSellerInput(e.target.value.toUpperCase())}
              placeholder="Vendedor..."
              autoFocus
              className="text-[11px] px-1.5 py-0.5 bg-white border-2 border-amber-500 rounded font-semibold text-slate-900 focus:outline-none w-28 uppercase"
            />
            <button
              type="submit"
              className="p-0.5 bg-emerald-600 text-white rounded hover:bg-emerald-700 cursor-pointer"
            >
              <Check className="w-3 h-3" />
            </button>
            <button
              type="button"
              onClick={() => {
                setSellerInput(passenger.seller);
                setIsEditingSeller(false);
              }}
              className="p-0.5 bg-slate-200 text-slate-600 rounded hover:bg-slate-300 cursor-pointer"
            >
              <X className="w-3 h-3" />
            </button>
          </form>
        ) : (
          <button
            type="button"
            onClick={() => {
              setSellerInput(passenger.seller);
              setIsEditingSeller(true);
            }}
            className="inline-flex items-center gap-1 px-2 py-1 rounded-lg bg-amber-50 hover:bg-amber-100 text-amber-900 border-2 border-amber-300 text-[11px] font-semibold transition cursor-pointer"
            title="Clique para alterar o vendedor"
          >
            <Tag className="w-3 h-3 text-amber-700 shrink-0" />
            <span className="max-w-[100px] truncate">VEND: {passenger.seller}</span>
            <Edit3 className="w-2.5 h-2.5 text-amber-700 opacity-60 shrink-0 ml-0.5" />
          </button>
        )}
      </div>

      {/* Col 4: Driver Selector Dropdown (Quick Allocation on the same row) */}
      <div className="shrink-0 flex items-center gap-1.5">
        <Car className="w-3.5 h-3.5 text-slate-400 shrink-0 hidden sm:block" />
        <select
          value={passenger.driverId || ''}
          onChange={(e) => onQuickAllocateDriver(passenger.id, e.target.value)}
          className={`text-[11px] font-semibold py-1 px-2 rounded-lg border-2 appearance-none cursor-pointer focus:outline-none focus:ring-1 focus:ring-emerald-500 transition max-w-[140px] truncate ${
            driver
              ? 'bg-emerald-50/90 text-emerald-900 border-emerald-300 hover:bg-emerald-100/70'
              : 'bg-slate-100 text-slate-700 border-slate-300 hover:bg-slate-200'
          }`}
          title="Selecione para definir ou alterar o motorista"
        >
          <option value="">A Definir</option>
          {drivers.map((d) => (
            <option key={d.id} value={d.id}>
              {d.fullName}
            </option>
          ))}
        </select>
      </div>

      {/* Col 5: Daily List Status & Quick Pull Button */}
      <div className="shrink-0">
        {onAddToDailyList && (
          <button
            type="button"
            onClick={() => onAddToDailyList(passenger.id)}
            className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-[11px] font-bold transition active:scale-95 cursor-pointer border-2 ${
              isInDailyList
                ? 'bg-emerald-100 text-emerald-900 border-emerald-400'
                : 'bg-white hover:bg-emerald-50 text-slate-700 hover:text-emerald-800 border-slate-300 shadow-2xs'
            }`}
            title={isInDailyList ? 'Cliente já está agendado na Lista do Dia' : 'Adicionar este cliente à Lista do Dia'}
          >
            {isInDailyList ? (
              <>
                <Check className="w-3 h-3 text-emerald-700" />
                <span>Na Lista</span>
              </>
            ) : (
              <>
                <Plus className="w-3 h-3 text-emerald-600" />
                <span>+ Puxar p/ Dia</span>
              </>
            )}
          </button>
        )}
      </div>

      {/* Col 6: Action Buttons (WhatsApp, Edit, Delete) */}
      <div className="flex items-center gap-1 shrink-0 ml-auto sm:ml-0">
        <button
          onClick={handleShareWhatsApp}
          title="Enviar comprovante no WhatsApp"
          className="p-1.5 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-emerald-200"
        >
          <Share2 className="w-3.5 h-3.5" />
        </button>

        <button
          onClick={() => onEdit(passenger)}
          title="Editar dados completos do passageiro"
          className="p-1.5 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-slate-300"
        >
          <Edit3 className="w-3.5 h-3.5" />
        </button>

        <button
          onClick={() => onDelete(passenger.id)}
          title="Excluir da lista geral"
          className="p-1.5 text-rose-500 hover:text-rose-700 hover:bg-rose-50 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-rose-200"
        >
          <Trash2 className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
};

src/components/PassengerCard.tsx:
import React, { useState } from 'react';
import { User, MapPin, Flag, ArrowRight, Tag, Car, Trash2, Edit3, Share2, UserCheck, Check, X, CalendarDays } from 'lucide-react';
import { Passenger, Driver } from '../types';

interface PassengerCardProps {
  passenger: Passenger;
  driver?: Driver;
  drivers: Driver[];
  onEdit: (passenger: Passenger) => void;
  onDelete: (id: string) => void;
  onSelectDriverManifest?: (driverId: string) => void;
  onQuickAllocateDriver: (passengerId: string, driverId: string) => void;
  onOpenAllocationModal: (passenger: Passenger) => void;
  onUpdateOrigin?: (passengerId: string, newOrigin: string) => void;
  onUpdateDestination: (passengerId: string, newDestination: string) => void;
  onUpdateSeller?: (passengerId: string, newSeller: string) => void;
  onAddToDailyList?: (passengerId: string) => void;
  isInDailyList?: boolean;
}

export const PassengerCard: React.FC<PassengerCardProps> = ({
  passenger,
  driver,
  drivers,
  onEdit,
  onDelete,
  onSelectDriverManifest,
  onQuickAllocateDriver,
  onOpenAllocationModal,
  onUpdateOrigin,
  onUpdateDestination,
  onUpdateSeller,
  onAddToDailyList,
  isInDailyList = false,
}) => {
  // Inline edit state for origin
  const [isEditingOrigin, setIsEditingOrigin] = useState(false);
  const [originInput, setOriginInput] = useState(passenger.origin);

  // Inline edit state for destination
  const [isEditingDestination, setIsEditingDestination] = useState(false);
  const [destinationInput, setDestinationInput] = useState(passenger.destination);

  // Inline edit state for seller
  const [isEditingSeller, setIsEditingSeller] = useState(false);
  const [sellerInput, setSellerInput] = useState(passenger.seller);

  const handleShareWhatsApp = () => {
    const text = `*COMPROVANTE DE EMBARQUE - TRANSPORTE*\n👤 *Passageiro:* ${passenger.fullName}\n📍 *Origem:* ${passenger.origin}\n🏁 *Destino:* ${passenger.destination}\n🏷️ *Vendedor:* ${passenger.seller}\n🚐 *Motorista:* ${driver ? driver.fullName : 'Não informado'}`;
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleSaveOrigin = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = originInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.origin && onUpdateOrigin) {
      onUpdateOrigin(passenger.id, trimmed);
    }
    setIsEditingOrigin(false);
  };

  const handleCancelOrigin = () => {
    setOriginInput(passenger.origin);
    setIsEditingOrigin(false);
  };

  const handleSaveDestination = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = destinationInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.destination) {
      onUpdateDestination(passenger.id, trimmed);
    }
    setIsEditingDestination(false);
  };

  const handleSaveSeller = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = sellerInput.trim().toUpperCase();
    if (trimmed && trimmed !== passenger.seller && onUpdateSeller) {
      onUpdateSeller(passenger.id, trimmed);
    }
    setIsEditingSeller(false);
  };

  const handleCancelDestination = () => {
    setDestinationInput(passenger.destination);
    setIsEditingDestination(false);
  };

  return (
    <div
      id={`passenger-card-${passenger.id}`}
      className={`bg-white rounded-2xl border-2 transition-all p-3.5 sm:p-4 relative shadow-2xs hover:shadow-xs ${
        driver ? 'border-slate-300' : 'border-amber-400 bg-amber-50/25'
      }`}
    >
      {/* Header: Passenger Name and actions */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center space-x-2.5">
          <div
            className={`w-9 h-9 rounded-xl border-2 flex items-center justify-center font-bold text-sm shrink-0 ${
              driver
                ? 'bg-emerald-50 border-emerald-300 text-emerald-800'
                : 'bg-amber-100 border-amber-400 text-amber-800'
            }`}
          >
            {passenger.fullName.charAt(0).toUpperCase()}
          </div>
          <div>
            <h3 className="text-sm sm:text-base font-bold text-slate-900 leading-tight">
              {passenger.fullName}
            </h3>
            <div className="flex items-center gap-1.5 mt-0.5">
              <span className="text-[11px] text-slate-500 font-medium">Passageiro</span>
              {!driver && (
                <span className="text-[10px] bg-amber-100 text-amber-900 font-bold px-1.5 py-0.5 rounded-md border border-amber-300">
                  Aguardando Motorista
                </span>
              )}
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-1">
          {onAddToDailyList && (
            <button
              onClick={() => onAddToDailyList(passenger.id)}
              title={isInDailyList ? 'Já adicionado à Lista do Dia' : 'Puxar para a Lista do Dia'}
              className={`p-1.5 rounded-lg transition cursor-pointer border-2 ${
                isInDailyList
                  ? 'text-emerald-800 bg-emerald-100 border-emerald-300 font-bold'
                  : 'text-slate-500 hover:text-emerald-700 hover:bg-emerald-50 border-transparent hover:border-emerald-200'
              }`}
            >
              <CalendarDays className="w-4 h-4" />
            </button>
          )}
          <button
            onClick={handleShareWhatsApp}
            title="Compartilhar detalhes no WhatsApp"
            className="p-1.5 text-emerald-600 hover:text-emerald-700 hover:bg-emerald-50 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-emerald-200"
          >
            <Share2 className="w-4 h-4" />
          </button>
          <button
            onClick={() => onEdit(passenger)}
            title="Editar cadastro completo"
            className="p-1.5 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-slate-300"
          >
            <Edit3 className="w-4 h-4" />
          </button>
          <button
            onClick={() => onDelete(passenger.id)}
            title="Excluir passageiro da lista geral"
            className="p-1.5 text-rose-500 hover:text-rose-700 hover:bg-rose-50 rounded-lg transition cursor-pointer border-2 border-transparent hover:border-rose-200"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Campos Separados: Cidade de Origem e Cidade de Destino */}
      <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
        {/* Campo 1: Cidade de Origem */}
        <div className="p-2.5 bg-emerald-50/40 rounded-xl border-2 border-emerald-300/80 shadow-2xs">
          <div className="flex items-center justify-between gap-1 mb-1">
            <div className="flex items-center gap-1 text-emerald-800">
              <MapPin className="w-3.5 h-3.5 text-emerald-700 shrink-0" />
              <span className="text-[10px] uppercase tracking-wider font-extrabold">
                Cidade de Origem
              </span>
            </div>
            {!isEditingOrigin && (
              <button
                type="button"
                onClick={() => {
                  setOriginInput(passenger.origin);
                  setIsEditingOrigin(true);
                }}
                className="text-slate-400 hover:text-emerald-700 p-0.5 rounded cursor-pointer transition"
                title="Alterar cidade de origem"
              >
                <Edit3 className="w-3 h-3 inline" />
              </button>
            )}
          </div>

          {isEditingOrigin ? (
            <form onSubmit={handleSaveOrigin} className="flex items-center gap-1 mt-1">
              <input
                type="text"
                value={originInput}
                onChange={(e) => setOriginInput(e.target.value.toUpperCase())}
                placeholder="Origem..."
                autoFocus
                className="text-xs px-2 py-1 bg-white border-2 border-emerald-500 rounded-md text-slate-900 font-semibold focus:outline-none w-full uppercase"
              />
              <button
                type="submit"
                className="p-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded cursor-pointer"
                title="Salvar origem"
              >
                <Check className="w-3 h-3" />
              </button>
              <button
                type="button"
                onClick={handleCancelOrigin}
                className="p-1 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded cursor-pointer"
                title="Cancelar"
              >
                <X className="w-3 h-3" />
              </button>
            </form>
          ) : (
            <button
              type="button"
              onClick={() => {
                setOriginInput(passenger.origin);
                setIsEditingOrigin(true);
              }}
              className="font-bold text-slate-900 truncate block w-full text-left hover:text-emerald-700 hover:underline cursor-pointer text-xs"
              title="Clique para alterar a cidade de origem"
            >
              {passenger.origin}
            </button>
          )}
        </div>

        {/* Campo 2: Cidade de Destino */}
        <div className="p-2.5 bg-rose-50/40 rounded-xl border-2 border-rose-300/80 shadow-2xs">
          <div className="flex items-center justify-between gap-1 mb-1">
            <div className="flex items-center gap-1 text-rose-800">
              <Flag className="w-3.5 h-3.5 text-rose-600 shrink-0" />
              <span className="text-[10px] uppercase tracking-wider font-extrabold">
                Cidade de Destino
              </span>
            </div>
            {!isEditingDestination && (
              <button
                type="button"
                onClick={() => {
                  setDestinationInput(passenger.destination);
                  setIsEditingDestination(true);
                }}
                className="text-slate-400 hover:text-rose-700 p-0.5 rounded cursor-pointer transition"
                title="Alterar cidade de destino"
              >
                <Edit3 className="w-3 h-3 inline" />
              </button>
            )}
          </div>

          {isEditingDestination ? (
            <form onSubmit={handleSaveDestination} className="flex items-center gap-1 mt-1">
              <input
                type="text"
                value={destinationInput}
                onChange={(e) => setDestinationInput(e.target.value.toUpperCase())}
                placeholder="Destino..."
                autoFocus
                className="text-xs px-2 py-1 bg-white border-2 border-rose-500 rounded-md text-slate-900 font-semibold focus:outline-none w-full uppercase"
              />
              <button
                type="submit"
                className="p-1 bg-rose-600 hover:bg-rose-700 text-white rounded cursor-pointer"
                title="Salvar destino"
              >
                <Check className="w-3 h-3" />
              </button>
              <button
                type="button"
                onClick={handleCancelDestination}
                className="p-1 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded cursor-pointer"
                title="Cancelar"
              >
                <X className="w-3 h-3" />
              </button>
            </form>
          ) : (
            <button
              type="button"
              onClick={() => {
                setDestinationInput(passenger.destination);
                setIsEditingDestination(true);
              }}
              className="font-bold text-rose-950 truncate block w-full text-left hover:text-rose-700 hover:underline cursor-pointer text-xs"
              title="Clique para alterar a cidade de destino"
            >
              {passenger.destination}
            </button>
          )}
        </div>
      </div>

      {/* Seller info */}
      <div className="mt-2.5 flex items-center justify-between text-xs text-slate-600">
        <div className="flex items-center space-x-1.5 flex-1 min-w-0">
          <Tag className="w-3.5 h-3.5 text-amber-500 shrink-0" />
          <span className="text-[11px] text-slate-500 shrink-0">Vendedor:</span>

          {isEditingSeller ? (
            <form onSubmit={handleSaveSeller} className="flex items-center gap-1">
              <input
                type="text"
                value={sellerInput}
                onChange={(e) => setSellerInput(e.target.value.toUpperCase())}
                placeholder="Novo vendedor..."
                autoFocus
                className="text-xs px-2 py-0.5 bg-white border border-amber-500 rounded-md text-slate-900 font-semibold focus:outline-none focus:ring-1 focus:ring-amber-500 w-36 uppercase"
              />
              <button
                type="submit"
                className="p-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded cursor-pointer"
                title="Salvar novo vendedor"
              >
                <Check className="w-3 h-3" />
              </button>
              <button
                type="button"
                onClick={() => {
                  setSellerInput(passenger.seller);
                  setIsEditingSeller(false);
                }}
                className="p-1 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded cursor-pointer"
                title="Cancelar"
              >
                <X className="w-3 h-3" />
              </button>
            </form>
          ) : (
            <div className="inline-flex items-center gap-1">
              <span className="font-semibold text-slate-700 text-[11px] bg-amber-50 border border-amber-200/60 px-2 py-0.5 rounded-md">
                {passenger.seller}
              </span>
              {onUpdateSeller && (
                <button
                  type="button"
                  onClick={() => {
                    setSellerInput(passenger.seller);
                    setIsEditingSeller(true);
                  }}
                  className="text-slate-400 hover:text-amber-800 p-0.5 rounded cursor-pointer transition"
                  title="Alterar vendedor desta passagem"
                >
                  <Edit3 className="w-3 h-3 inline" />
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Driver Allocation Section */}
      <div className="mt-2.5 pt-2.5 border-t-2 border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-2 text-xs">
        <div className="flex items-center space-x-1.5 flex-1 min-w-0">
          <span className="text-slate-600 font-semibold shrink-0">Motorista:</span>
          {driver ? (
            <button
              onClick={() => onSelectDriverManifest && onSelectDriverManifest(driver.id)}
              className="inline-flex items-center gap-1 px-2.5 py-1 bg-emerald-50 text-emerald-800 border-2 border-emerald-300 rounded-lg font-bold hover:bg-emerald-100 transition cursor-pointer truncate"
              title="Ver manifesto de passageiros deste motorista"
            >
              <Car className="w-3.5 h-3.5 text-emerald-600 shrink-0" />
              <span className="truncate">{driver.fullName}</span>
            </button>
          ) : (
            <span className="text-amber-800 font-semibold text-[11px] bg-amber-100 px-2 py-0.5 rounded-md border border-amber-300">
              Ainda não destinado
            </span>
          )}
        </div>

        {/* Quick Driver Allocation selector or button */}
        <div className="flex items-center gap-1.5 shrink-0">
          <div className="relative">
            <select
              value={passenger.driverId || ''}
              onChange={(e) => onQuickAllocateDriver(passenger.id, e.target.value)}
              className="text-xs font-semibold py-1 pl-2 pr-6 bg-slate-100 hover:bg-slate-200 border-2 border-slate-300 text-slate-700 rounded-lg appearance-none cursor-pointer focus:outline-none focus:ring-1 focus:ring-emerald-500"
              title="Mudar ou retirar motorista deste passageiro (não exclui da Lista Geral)"
            >
              <option value="">{driver ? 'Retirar motorista' : 'Alocar motorista...'}</option>
              {drivers.map((d) => (
                <option key={d.id} value={d.id}>
                  Alocar: {d.fullName}
                </option>
              ))}
            </select>
            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-1.5 text-slate-500">
              <svg className="w-3 h-3 fill-current" viewBox="0 0 20 20">
                <path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" />
              </svg>
            </div>
          </div>

          <button
            onClick={() => onOpenAllocationModal(passenger)}
            className="p-1 text-slate-500 hover:text-emerald-700 hover:bg-emerald-50 border-2 border-slate-200 hover:border-emerald-300 rounded-lg transition cursor-pointer"
            title="Abrir painel de alocação"
          >
            <UserCheck className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/DailyListManager.tsx:
import React, { useState, useMemo, useRef, useEffect } from 'react';
import {
  CalendarDays,
  UserPlus,
  Users,
  Search,
  Check,
  Plus,
  FileDown,
  RotateCcw,
  UserMinus,
  MapPin,
  Flag,
  Tag,
  Car,
  ChevronLeft,
  ChevronRight,
  AlertCircle,
  Sparkles,
  Info,
  X,
  CheckCircle2,
  ArrowDownRight,
  Database,
  Edit3,
  List,
  LayoutGrid,
} from 'lucide-react';
import { Driver, Passenger, CompanyConfig } from '../types';
import { generateDailyListPdf } from '../utils/pdfGenerator';

interface DailyListManagerProps {
  passengers: Passenger[];
  drivers: Driver[];
  dailyPassengerIds: string[];
  selectedDate: string;
  onSelectDate: (date: string) => void;
  onAddPassengerToDaily: (passengerId: string, customSeller?: string) => void;
  onAddMultiplePassengersToDaily: (passengerIds: string[]) => void;
  onRemovePassengerFromDaily: (passengerId: string) => void;
  onClearDailyList: () => void;
  onSaveNewPassengerAndAddToDaily: (newPassenger: Passenger) => void;
  onUpdatePassengerDriver: (passengerId: string, driverId: string) => void;
  onUpdatePassengerSeller?: (passengerId: string, newSeller: string) => void;
  companyConfig?: CompanyConfig;
}

export const DailyListManager: React.FC<DailyListManagerProps> = ({
  passengers,
  drivers,
  dailyPassengerIds,
  selectedDate,
  onSelectDate,
  onAddPassengerToDaily,
  onAddMultiplePassengersToDaily,
  onRemovePassengerFromDaily,
  onClearDailyList,
  onSaveNewPassengerAndAddToDaily,
  onUpdatePassengerDriver,
  onUpdatePassengerSeller,
  companyConfig,
}) => {
  // Modals state
  const [isPullModalOpen, setIsPullModalOpen] = useState(false);
  const [isNewClientModalOpen, setIsNewClientModalOpen] = useState(false);
  const [isConfirmClearOpen, setIsConfirmClearOpen] = useState(false);
  const [passengerToRemove, setPassengerToRemove] = useState<Passenger | null>(null);

  // Seller alteration state (when pulling or updating)
  const [sellerEditPassenger, setSellerEditPassenger] = useState<Passenger | null>(null);
  const [isPullingAfterSellerEdit, setIsPullingAfterSellerEdit] = useState(false);
  const [customSellerInput, setCustomSellerInput] = useState('');
  const [isBulkSellerModalOpen, setIsBulkSellerModalOpen] = useState(false);
  const [bulkSellerInput, setBulkSellerInput] = useState('');

  // Search inside daily list
  const [dailySearch, setDailySearch] = useState('');
  // View mode: single-line list (default) or cards
  const [dailyViewMode, setDailyViewMode] = useState<'list' | 'cards'>('list');

  // Pull modal state
  const [pullSearch, setPullSearch] = useState('');
  const [selectedToPull, setSelectedToPull] = useState<string[]>([]);

  // New Client Form state
  const [newFullName, setNewFullName] = useState('');
  const [newOrigin, setNewOrigin] = useState('');
  const [newDestination, setNewDestination] = useState('');
  const [newSeller, setNewSeller] = useState('');
  const [newDriverId, setNewDriverId] = useState('');
  const [formError, setFormError] = useState<string | null>(null);
  const [autoPulledNoticeModal, setAutoPulledNoticeModal] = useState<string | null>(null);
  const [isModalSuggestionsOpen, setIsModalSuggestionsOpen] = useState(false);
  const modalSuggestionsRef = useRef<HTMLDivElement>(null);

  // Close modal suggestions on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (modalSuggestionsRef.current && !modalSuggestionsRef.current.contains(e.target as Node)) {
        setIsModalSuggestionsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Driver dictionary
  const driverMap = useMemo(() => {
    const map = new Map<string, Driver>();
    drivers.forEach((d) => map.set(d.id, d));
    return map;
  }, [drivers]);

  // Passenger dictionary
  const passengerMap = useMemo(() => {
    const map = new Map<string, Passenger>();
    passengers.forEach((p) => map.set(p.id, p));
    return map;
  }, [passengers]);

  // Passengers currently in the daily list
  const currentDailyPassengers = useMemo(() => {
    return dailyPassengerIds
      .map((id) => passengerMap.get(id))
      .filter((p): p is Passenger => p !== undefined);
  }, [dailyPassengerIds, passengerMap]);

  // Filtered daily passengers (by search box)
  const filteredDailyPassengers = useMemo(() => {
    const query = dailySearch.trim().toLowerCase();
    if (!query) return currentDailyPassengers;
    return currentDailyPassengers.filter((p) => {
      const driver = p.driverId ? driverMap.get(p.driverId)?.fullName.toLowerCase() || '' : '';
      return (
        p.fullName.toLowerCase().includes(query) ||
        p.origin.toLowerCase().includes(query) ||
        p.destination.toLowerCase().includes(query) ||
        p.seller.toLowerCase().includes(query) ||
        driver.includes(query)
      );
    });
  }, [currentDailyPassengers, dailySearch, driverMap]);

  // Existing passengers available in general list for pull modal
  const pullFilteredPassengers = useMemo(() => {
    const query = pullSearch.trim().toLowerCase();
    if (!query) return passengers;
    return passengers.filter((p) => {
      const driver = p.driverId ? driverMap.get(p.driverId)?.fullName.toLowerCase() || '' : '';
      return (
        p.fullName.toLowerCase().includes(query) ||
        p.origin.toLowerCase().includes(query) ||
        p.destination.toLowerCase().includes(query) ||
        p.seller.toLowerCase().includes(query) ||
        driver.includes(query)
      );
    });
  }, [passengers, pullSearch, driverMap]);

  // Quick suggestions for origins, destinations and sellers from existing database
  const suggestedOrigins = useMemo(() => {
    const set = new Set<string>();
    passengers.forEach((p) => {
      if (p.origin) set.add(p.origin.trim());
    });
    return Array.from(set).slice(0, 5);
  }, [passengers]);

  const suggestedDestinations = useMemo(() => {
    const set = new Set<string>();
    passengers.forEach((p) => {
      if (p.destination) set.add(p.destination.trim());
    });
    return Array.from(set).slice(0, 5);
  }, [passengers]);

  const suggestedSellers = useMemo(() => {
    const set = new Set<string>();
    passengers.forEach((p) => {
      if (p.seller) set.add(p.seller.trim());
    });
    return Array.from(set).slice(0, 5);
  }, [passengers]);

  // Detect if typed name in new client form matches someone in General List
  const existingMatchesInGeneralList = useMemo(() => {
    const trimmed = newFullName.trim().toLowerCase();
    if (trimmed.length < 2) return [];
    return passengers.filter((p) => p.fullName.toLowerCase().includes(trimmed)).slice(0, 5);
  }, [newFullName, passengers]);

  // Exact match detection in General List
  const exactMatchInGeneralList = useMemo(() => {
    const trimmed = newFullName.trim().toLowerCase();
    if (trimmed.length < 3) return null;
    return passengers.find((p) => p.fullName.trim().toLowerCase() === trimmed) || null;
  }, [newFullName, passengers]);

  // Handler to auto-fill form with matching customer data
  const handleAutoFillFromMatch = (match: Passenger) => {
    setNewFullName(match.fullName);
    setNewOrigin(match.origin);
    setNewDestination(match.destination);
    setNewSeller(match.seller);
    if (match.driverId) {
      setNewDriverId(match.driverId);
    }
    setIsModalSuggestionsOpen(false);
    setAutoPulledNoticeModal(`Dados de "${match.fullName}" puxados automaticamente da base de dados!`);
  };

  // Open seller editor modal
  const openSellerEditor = (passenger: Passenger, andPull: boolean = false) => {
    setSellerEditPassenger(passenger);
    setIsPullingAfterSellerEdit(andPull);
    setCustomSellerInput(passenger.seller);
  };

  // Save seller alteration
  const handleSaveSellerEdit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!sellerEditPassenger) return;

    const newSeller = customSellerInput.trim().toUpperCase() || sellerEditPassenger.seller.toUpperCase();

    if (onUpdatePassengerSeller) {
      onUpdatePassengerSeller(sellerEditPassenger.id, newSeller);
    }

    if (isPullingAfterSellerEdit) {
      onAddPassengerToDaily(sellerEditPassenger.id, newSeller);
    }

    setSellerEditPassenger(null);
    setIsPullingAfterSellerEdit(false);
    setCustomSellerInput('');
  };

  // Bulk pull with custom seller
  const handleConfirmBulkPullWithSeller = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const seller = bulkSellerInput.trim().toUpperCase();
    if (seller && onUpdatePassengerSeller) {
      selectedToPull.forEach((id) => {
        onUpdatePassengerSeller(id, seller);
      });
    }
    onAddMultiplePassengersToDaily(selectedToPull);
    setSelectedToPull([]);
    setIsPullModalOpen(false);
    setIsBulkSellerModalOpen(false);
    setBulkSellerInput('');
  };

  // Handler to directly pull existing customer into today's list
  const handleDirectPullMatch = (match: Passenger) => {
    onAddPassengerToDaily(match.id);
    setIsNewClientModalOpen(false);
    setIsModalSuggestionsOpen(false);
    setNewFullName('');
    setNewOrigin('');
    setNewDestination('');
    setNewSeller('');
    setNewDriverId('');
    setAutoPulledNoticeModal(null);
  };

  // Navigation helpers for dates
  const changeDateByDays = (days: number) => {
    const current = new Date(selectedDate + 'T12:00:00');
    current.setDate(current.getDate() + days);
    const newY = current.getFullYear();
    const newM = String(current.getMonth() + 1).padStart(2, '0');
    const newD = String(current.getDate()).padStart(2, '0');
    onSelectDate(`${newY}-${newM}-${newD}`);
  };

  const setDateToToday = () => {
    const today = new Date();
    const y = today.getFullYear();
    const m = String(today.getMonth() + 1).padStart(2, '0');
    const d = String(today.getDate()).padStart(2, '0');
    onSelectDate(`${y}-${m}-${d}`);
  };

  // Formatted date string for header
  const formattedDateTitle = useMemo(() => {
    try {
      const parts = selectedDate.split('-');
      if (parts.length === 3) {
        const d = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
        return d.toLocaleDateString('pt-BR', {
          weekday: 'long',
          day: '2-digit',
          month: 'long',
          year: 'numeric',
        });
      }
    } catch {
      // Fallback
    }
    return selectedDate;
  }, [selectedDate]);

  // Handle saving new client from the Daily List modal
  const handleSaveNewClient = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    const name = newFullName.trim();
    const origin = newOrigin.trim();
    const dest = newDestination.trim();
    const seller = newSeller.trim();

    if (!name) {
      setFormError('Informe o nome completo do cliente.');
      return;
    }
    if (!origin) {
      setFormError('Informe a origem da viagem.');
      return;
    }
    if (!dest) {
      setFormError('Informe o destino da viagem.');
      return;
    }
    if (!seller) {
      setFormError('Informe o vendedor responsável.');
      return;
    }

    const newPassenger: Passenger = {
      id: 'pass_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7),
      fullName: name.toUpperCase(),
      origin: origin.toUpperCase(),
      destination: dest.toUpperCase(),
      seller: seller.toUpperCase(),
      driverId: newDriverId,
      createdAt: new Date().toISOString(),
    };

    onSaveNewPassengerAndAddToDaily(newPassenger);

    // Reset form
    setNewFullName('');
    setNewOrigin('');
    setNewDestination('');
    setNewSeller('');
    setNewDriverId('');
    setIsNewClientModalOpen(false);
  };

  // Handle pull selection toggle
  const togglePullSelection = (id: string) => {
    setSelectedToPull((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleConfirmPullSelection = () => {
    if (selectedToPull.length === 0) return;
    onAddMultiplePassengersToDaily(selectedToPull);
    setSelectedToPull([]);
    setIsPullModalOpen(false);
  };

  return (
    <div className="space-y-4">
      {/* Top Banner / Date Control Card */}
      <div className="bg-white rounded-2xl p-4 shadow-sm border-2 border-slate-300 space-y-3">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b-2 border-slate-200 pb-3">
          <div className="flex items-center space-x-2.5">
            <div className="w-9 h-9 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center font-bold border-2 border-emerald-300">
              <CalendarDays className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base font-bold text-slate-900 flex items-center gap-1.5">
                <span>Lista do Dia</span>
                <span className="text-xs px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-800 font-bold border-2 border-emerald-300">
                  {currentDailyPassengers.length} cliente(s)
                </span>
              </h2>
              <p className="text-xs text-slate-500 uppercase font-medium">
                {formattedDateTitle}
              </p>
            </div>
          </div>

          {/* Date Selector & Fast Nav */}
          <div className="flex items-center gap-1.5 bg-slate-50 p-1 rounded-xl border-2 border-slate-300">
            <button
              onClick={() => changeDateByDays(-1)}
              title="Dia anterior"
              className="p-1.5 text-slate-600 hover:text-slate-900 hover:bg-slate-200/70 rounded-lg transition cursor-pointer"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>

            <input
              type="date"
              value={selectedDate}
              onChange={(e) => onSelectDate(e.target.value)}
              className="bg-transparent text-xs font-semibold text-slate-800 px-1 py-1 focus:outline-hidden cursor-pointer"
            />

            <button
              onClick={() => changeDateByDays(1)}
              title="Próximo dia"
              className="p-1.5 text-slate-600 hover:text-slate-900 hover:bg-slate-200/70 rounded-lg transition cursor-pointer"
            >
              <ChevronRight className="w-4 h-4" />
            </button>

            <button
              onClick={setDateToToday}
              className="px-2 py-1 bg-white hover:bg-slate-100 text-[11px] font-bold text-emerald-800 rounded-lg border-2 border-slate-300 shadow-2xs transition cursor-pointer"
            >
              Hoje
            </button>
          </div>
        </div>

        {/* Primary Action Buttons: Puxar da Lista Geral, Novo Cliente, Gerar PDF, Zerar */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 pt-1">
          {/* Button 1: Puxar da Lista Geral */}
          <button
            id="btn-pull-from-general"
            onClick={() => {
              setPullSearch('');
              setSelectedToPull([]);
              setIsPullModalOpen(true);
            }}
            className="flex items-center justify-center gap-1.5 px-3 py-2.5 bg-emerald-700 hover:bg-emerald-800 active:scale-[0.98] text-white text-xs font-bold rounded-xl shadow-xs transition cursor-pointer border-2 border-emerald-900"
            title="Importar ou selecionar clientes já cadastrados na Lista Geral"
          >
            <Users className="w-4 h-4 text-emerald-200" />
            <span>Puxar da Lista Geral</span>
          </button>

          {/* Button 2: Novo Cliente (salva na lista do dia e alimenta a lista geral) */}
          <button
            id="btn-new-client-daily"
            onClick={() => {
              setFormError(null);
              setIsNewClientModalOpen(true);
            }}
            className="flex items-center justify-center gap-1.5 px-3 py-2.5 bg-emerald-600 hover:bg-emerald-700 active:scale-[0.98] text-white text-xs font-bold rounded-xl shadow-xs transition cursor-pointer border-2 border-emerald-800"
            title="Cadastrar novo cliente: adiciona à lista do dia e salva automaticamente na Lista Geral permanente"
          >
            <UserPlus className="w-4 h-4" />
            <span>+ Novo Cliente</span>
          </button>

          {/* Button 3: Gerar PDF */}
          <button
            id="btn-pdf-daily"
            onClick={() => {
              generateDailyListPdf(selectedDate, currentDailyPassengers, drivers, companyConfig);
            }}
            className="flex items-center justify-center gap-1.5 px-3 py-2.5 bg-slate-800 hover:bg-slate-900 active:scale-[0.98] text-white text-xs font-bold rounded-xl shadow-xs transition cursor-pointer border-2 border-slate-950"
            title="Baixar lista em PDF para conferência, controle de embarque ou impressão"
          >
            <FileDown className="w-4 h-4 text-slate-300" />
            <span>Gerar PDF</span>
          </button>

          {/* Button 4: Zerar Lista do Dia */}
          <button
            id="btn-clear-daily"
            onClick={() => setIsConfirmClearOpen(true)}
            disabled={currentDailyPassengers.length === 0}
            className={`flex items-center justify-center gap-1.5 px-3 py-2.5 text-xs font-bold rounded-xl border-2 transition cursor-pointer ${
              currentDailyPassengers.length === 0
                ? 'bg-slate-100 text-slate-400 border-slate-300 cursor-not-allowed opacity-60'
                : 'bg-amber-50 hover:bg-amber-100 text-amber-900 border-amber-400 active:scale-[0.98]'
            }`}
            title="Zerar passageiros agendados para este dia (mantém clientes salvos na Lista Geral)"
          >
            <RotateCcw className="w-4 h-4 text-amber-600" />
            <span>Zerar Lista</span>
          </button>
        </div>

        {/* Explain Card */}
        <div className="bg-emerald-50/60 border-2 border-emerald-200 rounded-xl p-2.5 flex items-start gap-2 text-xs text-emerald-900">
          <Info className="w-4 h-4 text-emerald-700 shrink-0 mt-0.5" />
          <p className="text-[11px] leading-relaxed text-emerald-950/80">
            Você pode <strong>puxar contatos da Lista Geral</strong> ou cadastrar <strong>novos clientes</strong>. Ao cadastrar um novo cliente aqui, ele é salvo automaticamente na <strong>Lista Geral</strong> para continuar alimentando a base permanente do sistema.
          </p>
        </div>
      </div>

      {/* Search Filter for Current Day */}
      {currentDailyPassengers.length > 0 && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
          <input
            type="text"
            placeholder="Pesquisar cliente, destino, vendedor ou motorista nesta lista..."
            value={dailySearch}
            onChange={(e) => setDailySearch(e.target.value)}
            className="w-full pl-9 pr-8 py-2.5 bg-white border-2 border-slate-300 rounded-xl text-xs text-slate-800 placeholder-slate-400 focus:outline-hidden focus:ring-2 focus:ring-emerald-600 shadow-2xs font-medium"
          />
          {dailySearch && (
            <button
              onClick={() => setDailySearch('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-1"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      )}

      {/* Daily List Items Display */}
      {currentDailyPassengers.length === 0 ? (
        <div className="bg-white rounded-2xl p-8 text-center border-2 border-dashed border-slate-300 space-y-4 shadow-2xs">
          <div className="w-14 h-14 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto text-emerald-700 border border-emerald-200/60">
            <CalendarDays className="w-7 h-7" />
          </div>
          <div className="max-w-xs mx-auto space-y-1">
            <h3 className="text-sm font-bold text-slate-800">
              Nenhum passageiro na Lista do Dia
            </h3>
            <p className="text-xs text-slate-500">
