                    onChange={(e) => setBulkSellerInput(e.target.value.toUpperCase())}
                    placeholder="Digite o nome do vendedor..."
                    autoFocus
                    className="w-full pl-9 pr-3 py-2 text-xs font-semibold bg-white border border-slate-300 rounded-xl focus:border-amber-500 focus:ring-1 focus:ring-amber-500 uppercase tracking-wide placeholder:normal-case transition"
                  />
                </div>
              </div>

              {/* Suggestions */}
              {suggestedSellers.length > 0 && (
                <div className="space-y-1.5">
                  <span className="text-[11px] font-semibold text-slate-500">
                    Vendedores frequentes (clique para preencher):
                  </span>
                  <div className="flex flex-wrap gap-1.5">
                    {suggestedSellers.map((sellerName) => (
                      <button
                        key={sellerName}
                        type="button"
                        onClick={() => setBulkSellerInput(sellerName.toUpperCase())}
                        className={`text-[11px] font-medium px-2 py-1 rounded-lg border transition cursor-pointer ${
                          bulkSellerInput.toUpperCase() === sellerName.toUpperCase()
                            ? 'bg-amber-100 border-amber-400 text-amber-900 font-bold'
                            : 'bg-slate-50 hover:bg-slate-100 border-slate-200 text-slate-700'
                        }`}
                      >
                        {sellerName}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-end space-x-2 pt-2 border-t border-slate-100">
                <button
                  type="button"
                  onClick={() => setIsBulkSellerModalOpen(false)}
                  className="px-3.5 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition cursor-pointer"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 text-xs font-bold bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl shadow-xs transition active:scale-95 cursor-pointer inline-flex items-center gap-1.5"
                >
                  <Check className="w-4 h-4" />
                  <span>Confirmar e Puxar Todos</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/DriverList.tsx:
import React, { useState } from 'react';
import { UserCheck, Car, Users, PlusCircle, Trash2, FileText, FileDown, RotateCcw } from 'lucide-react';
import { Driver, Passenger, CompanyConfig } from '../types';
import { generateDriverTripPdf } from '../utils/pdfGenerator';

interface DriverListProps {
  drivers: Driver[];
  passengers: Passenger[];
  onOpenAddDriver: () => void;
  onDeleteDriver: (id: string) => void;
  onClearDriverPassengers: (driverId: string) => void;
  onViewManifest: (driver: Driver) => void;
  companyConfig?: CompanyConfig;
}

export const DriverList: React.FC<DriverListProps> = ({
  drivers,
  passengers,
  onOpenAddDriver,
  onDeleteDriver,
  onClearDriverPassengers,
  onViewManifest,
  companyConfig,
}) => {
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [driverToClear, setDriverToClear] = useState<Driver | null>(null);

  const getPassengerCountForDriver = (driverId: string) => {
    return passengers.filter((p) => p.driverId === driverId).length;
  };

  const handleDownloadPdf = (driver: Driver, e: React.MouseEvent) => {
    e.stopPropagation();
    generateDriverTripPdf(driver, passengers, companyConfig);
  };

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between pb-1">
        <div>
          <h2 className="text-sm sm:text-base font-bold text-slate-900">
            Guia do Motorista
          </h2>
          <p className="text-xs text-slate-500">
            Gerencie motoristas e gere o PDF com a lista de passageiros
          </p>
        </div>
        <button
          id="driver-list-add-btn"
          onClick={onOpenAddDriver}
          className="inline-flex items-center gap-1.5 px-3 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-xs transition active:scale-95 cursor-pointer border-2 border-emerald-700"
        >
          <PlusCircle className="w-4 h-4" />
          <span>Novo Motorista</span>
        </button>
      </div>

      {drivers.length === 0 ? (
        <div className="bg-white rounded-2xl border-2 border-dashed border-slate-300 p-8 text-center">
          <div className="w-12 h-12 rounded-2xl bg-emerald-50 border-2 border-emerald-300 flex items-center justify-center mx-auto mb-3 text-emerald-600">
            <Car className="w-6 h-6" />
          </div>
          <h3 className="text-sm font-bold text-slate-800">
            Nenhum motorista cadastrado
          </h3>
          <p className="text-xs text-slate-500 mt-1 max-w-xs mx-auto mb-4">
            Cadastre um motorista com o nome completo para destinar os passageiros e emitir o PDF da viagem.
          </p>
          <button
            onClick={onOpenAddDriver}
            className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-xs transition inline-flex items-center gap-1.5 cursor-pointer border-2 border-emerald-700"
          >
            <UserCheck className="w-4 h-4" />
            <span>Cadastrar Primeiro Motorista</span>
          </button>
        </div>
      ) : (
        <div className="space-y-2.5">
          {drivers.map((driver) => {
            const count = getPassengerCountForDriver(driver.id);
            const isConfirming = confirmDeleteId === driver.id;

            return (
              <div
                key={driver.id}
                id={`driver-row-${driver.id}`}
                className="bg-white rounded-2xl border-2 border-slate-300 shadow-2xs p-4 flex flex-col gap-3 hover:border-slate-400 transition"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center font-bold text-sm shrink-0 border-2 border-emerald-300">
                      <Car className="w-5 h-5" />
                    </div>
                    <div>
                      <h3 className="text-sm font-bold text-slate-900 leading-tight">
                        {driver.fullName}
                      </h3>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="inline-flex items-center gap-1 text-xs font-semibold text-slate-700 bg-slate-100 border-2 border-slate-200 px-2 py-0.5 rounded-md">
                          <Users className="w-3 h-3 text-slate-500" />
                          <span>{count} {count === 1 ? 'passageiro' : 'passageiros'}</span>
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Actions for delete */}
                  {isConfirming ? (
                    <div className="flex items-center gap-1 bg-rose-50 p-1 rounded-lg border-2 border-rose-300">
                      <button
                        onClick={() => {
                          onDeleteDriver(driver.id);
                          setConfirmDeleteId(null);
                        }}
                        className="px-2 py-1 bg-rose-600 text-white text-[11px] font-bold rounded hover:bg-rose-700 transition cursor-pointer"
                      >
                        Confirmar
                      </button>
                      <button
                        onClick={() => setConfirmDeleteId(null)}
                        className="px-2 py-1 text-slate-600 text-[11px] hover:text-slate-800 transition cursor-pointer"
                      >
                        Cancelar
                      </button>
                    </div>
                  ) : (
                    <button
                      onClick={() => setConfirmDeleteId(driver.id)}
                      className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition border-2 border-transparent hover:border-rose-200"
                      title="Excluir motorista"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  )}
                </div>

                {/* Primary Button Bar: PDF generator, View manifest, and Zerar Passageiros */}
                <div className="flex flex-wrap sm:flex-nowrap items-center gap-2 pt-2 border-t-2 border-slate-200">
                  <button
                    id={`btn-generate-pdf-${driver.id}`}
                    onClick={(e) => handleDownloadPdf(driver, e)}
                    className="flex-1 min-w-[130px] inline-flex items-center justify-center gap-1.5 px-3 py-2 bg-emerald-700 hover:bg-emerald-800 active:scale-[0.98] text-white text-xs font-bold rounded-xl shadow-xs transition cursor-pointer border-2 border-emerald-900"
                    title="Baixar PDF da viagem com nome completo, origem, destino e vendedor da passagem"
                  >
                    <FileDown className="w-4 h-4 text-emerald-200" />
                    <span>Gerar PDF</span>
                  </button>

                  <button
                    onClick={() => onViewManifest(driver)}
                    className="inline-flex items-center justify-center gap-1 px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl transition cursor-pointer border-2 border-slate-300"
                    title="Ver manifesto na tela"
                  >
                    <FileText className="w-3.5 h-3.5 text-slate-600" />
                    <span>Ver</span>
                  </button>

                  <button
                    id={`btn-clear-passengers-${driver.id}`}
                    onClick={() => setDriverToClear(driver)}
                    disabled={count === 0}
                    className={`inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs font-bold rounded-xl transition cursor-pointer border-2 ${
                      count === 0
                        ? 'bg-slate-100 text-slate-400 border-slate-200/60 cursor-not-allowed opacity-60'
                        : 'bg-amber-50 hover:bg-amber-100 text-amber-900 border-amber-300 active:scale-95'
                    }`}
                    title={
                      count === 0
                        ? 'Nenhum passageiro vinculado a este motorista no momento'
                        : 'Zerar passageiros deste motorista (mantém clientes na Lista Geral e no histórico de viagens)'
                    }
                  >
                    <RotateCcw className="w-3.5 h-3.5 text-amber-600" />
                    <span>Zerar Passageiros</span>
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Confirmation Modal to Clear Driver Passengers */}
      {driverToClear && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-xs animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl max-w-md w-full p-5 shadow-2xl border border-slate-200 space-y-4">
            <div className="flex items-start space-x-3">
              <div className="w-10 h-10 rounded-xl bg-amber-100 text-amber-700 flex items-center justify-center shrink-0 border border-amber-200">
                <RotateCcw className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-sm font-bold text-slate-900">
                  Zerar Passageiros do Motorista
                </h3>
                <p className="text-xs text-slate-500 mt-0.5">
                  Motorista: <strong className="text-slate-800">{driverToClear.fullName}</strong>
                </p>
              </div>
            </div>

            <div className="bg-slate-50 rounded-xl p-3.5 border border-slate-200 text-xs space-y-2.5">
              <p className="text-slate-700 leading-relaxed">
                Esta ação irá desvincular os <strong>{getPassengerCountForDriver(driverToClear.id)} passageiro(s)</strong> deste motorista para liberá-lo para uma nova escala de viagem.
              </p>

              <div className="pt-2 border-t border-slate-200 space-y-2 text-[11px] text-slate-600">
                <div className="flex items-start gap-1.5 text-emerald-800">
                  <span className="font-bold text-emerald-600 shrink-0">✓</span>
                  <span><strong>Lista Geral Preservada:</strong> Os clientes NÃO serão excluídos do sistema. Eles continuarão disponíveis na Lista Geral para novas destinações.</span>
                </div>
                <div className="flex items-start gap-1.5 text-emerald-800">
                  <span className="font-bold text-emerald-600 shrink-0">✓</span>
                  <span><strong>Histórico de Viagens Preservado:</strong> Todas as viagens já cadastradas na guia Viagens continuarão salvas com seus passageiros para relatórios e controle.</span>
                </div>
              </div>
            </div>

            <div className="flex items-center justify-end space-x-2 pt-1">
              <button
                type="button"
                onClick={() => setDriverToClear(null)}
                className="px-3.5 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition cursor-pointer"
              >
                Cancelar
              </button>
              <button
                type="button"
                id="btn-confirm-clear-passengers"
                onClick={() => {
                  onClearDriverPassengers(driverToClear.id);
                  setDriverToClear(null);
                }}
                className="px-4 py-2 text-xs font-bold bg-amber-600 hover:bg-amber-700 text-white rounded-xl shadow-xs transition active:scale-95 cursor-pointer inline-flex items-center gap-1.5"
              >
                <RotateCcw className="w-4 h-4" />
                <span>Sim, Zerar Passageiros</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/DriverModal.tsx:
import React, { useState } from 'react';
import { X, UserCheck, CheckCircle2 } from 'lucide-react';
import { Driver } from '../types';

interface DriverModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSaveDriver: (driver: Driver) => void;
  existingDrivers: Driver[];
}

export const DriverModal: React.FC<DriverModalProps> = ({
  isOpen,
  onClose,
  onSaveDriver,
  existingDrivers,
}) => {
  const [fullName, setFullName] = useState('');
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = fullName.trim();
    if (!trimmed) {
      setError('Por favor, informe o nome completo do motorista.');
      return;
    }

    if (trimmed.length < 3) {
      setError('O nome do motorista deve conter ao menos 3 caracteres.');
      return;
    }

    const alreadyExists = existingDrivers.some(
      (d) => d.fullName.toLowerCase() === trimmed.toLowerCase()
    );

    if (alreadyExists) {
      setError('Já existe um motorista cadastrado com este nome.');
      return;
    }

    const newDriver: Driver = {
      id: `drv-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      fullName: trimmed.toUpperCase(),
      createdAt: new Date().toISOString(),
    };

    onSaveDriver(newDriver);
    setSuccessMsg('Motorista cadastrado com sucesso!');
    setFullName('');
    setError('');

    setTimeout(() => {
      setSuccessMsg('');
      onClose();
    }, 600);
  };

  return (
    <div
      id="driver-modal-backdrop"
      className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        id="driver-modal-content"
        role="dialog"
        aria-modal="true"
        aria-labelledby="driver-modal-title"
        className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-150"
      >
        <div className="bg-emerald-700 px-5 py-4 text-white flex items-center justify-between">
          <div className="flex items-center space-x-2.5">
            <div className="p-2 bg-emerald-600 rounded-lg">
              <UserCheck className="w-5 h-5 text-emerald-100" />
            </div>
            <div>
              <h2 id="driver-modal-title" className="font-bold text-base leading-tight">
                Cadastro de Motorista
              </h2>
              <p className="text-xs text-emerald-100/80">
                Informe o nome completo do motorista
              </p>
            </div>
          </div>
          <button
            id="driver-modal-close-btn"
            onClick={onClose}
            className="text-emerald-200 hover:text-white hover:bg-emerald-600/60 rounded-lg p-1.5 transition"
            aria-label="Fechar modal"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-5 space-y-4">
          {error && (
            <div
              id="driver-modal-error"
              className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-rose-700 text-xs font-medium"
            >
              {error}
            </div>
          )}

          {successMsg && (
            <div
              id="driver-modal-success"
              className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl text-emerald-700 text-xs font-medium flex items-center gap-2"
            >
              <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
              <span>{successMsg}</span>
            </div>
          )}

          <div>
            <label
              htmlFor="driver-fullname-input"
              className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-1.5"
            >
              Nome Completo do Motorista *
            </label>
            <input
              id="driver-fullname-input"
              type="text"
              value={fullName}
              onChange={(e) => {
                setFullName(e.target.value);
                if (error) setError('');
              }}
              placeholder="Ex: Roberto Carlos de Oliveira"
              className="w-full px-3.5 py-2.5 text-sm bg-slate-50 border border-slate-300 rounded-xl focus:bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 transition text-slate-800 placeholder-slate-400"
              autoFocus
            />
            <p className="text-[11px] text-slate-500 mt-1">
              Obrigatório para destinar os passageiros nas viagens.
            </p>
          </div>

          <div className="flex items-center justify-end gap-2.5 pt-2 border-t border-slate-100">
            <button
              id="driver-modal-cancel-btn"
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 text-xs font-semibold text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-xl transition cursor-pointer"
            >
              Cancelar
            </button>
            <button
              id="driver-modal-save-btn"
              type="submit"
              className="px-5 py-2.5 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white rounded-xl shadow-sm transition flex items-center gap-1.5 cursor-pointer"
            >
              <UserCheck className="w-4 h-4" />
              <span>Salvar Motorista</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

src/components/DriverAllocationModal.tsx:
import React, { useState } from 'react';
import { X, Car, UserCheck, Check, AlertCircle } from 'lucide-react';
import { Passenger, Driver } from '../types';

interface DriverAllocationModalProps {
  passenger: Passenger | null;
  drivers: Driver[];
  isOpen: boolean;
  onClose: () => void;
  onAllocateDriver: (passengerId: string, driverId: string) => void;
  onOpenAddDriver: () => void;
}

export const DriverAllocationModal: React.FC<DriverAllocationModalProps> = ({
  passenger,
  drivers,
  isOpen,
  onClose,
  onAllocateDriver,
  onOpenAddDriver,
}) => {
  const [selectedDriverId, setSelectedDriverId] = useState<string>('');

  React.useEffect(() => {
    if (passenger) {
      setSelectedDriverId(passenger.driverId || '');
    }
  }, [passenger, isOpen]);

  if (!isOpen || !passenger) return null;

  const handleSave = () => {
    onAllocateDriver(passenger.id, selectedDriverId);
    onClose();
  };

  return (
    <div
      id="driver-allocation-backdrop"
      className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        id="driver-allocation-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="driver-allocation-title"
        className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-150 flex flex-col"
      >
        {/* Header */}
        <div className="bg-emerald-800 px-5 py-4 text-white flex items-center justify-between">
          <div className="flex items-center space-x-2.5">
            <div className="w-9 h-9 rounded-xl bg-emerald-700 border border-emerald-500/30 flex items-center justify-center">
              <Car className="w-5 h-5 text-emerald-200" />
            </div>
            <div>
              <h2 id="driver-allocation-title" className="font-bold text-sm leading-tight">
                Alocar Motorista
              </h2>
              <p className="text-[11px] text-emerald-200/90 font-medium truncate max-w-[200px]">
                {passenger.fullName}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-emerald-200 hover:text-white hover:bg-emerald-700 rounded-lg p-1.5 transition cursor-pointer"
            aria-label="Fechar"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-4 space-y-3.5">
          {/* Passenger details card summary */}
          <div className="bg-slate-50 border border-slate-200/80 rounded-xl p-3 text-xs space-y-1">
            <div className="flex justify-between items-center text-slate-700">
              <span className="text-slate-500 font-medium">Passageiro:</span>
              <span className="font-bold text-slate-900">{passenger.fullName}</span>
            </div>
            <div className="flex justify-between items-center text-slate-700">
              <span className="text-slate-500 font-medium">Origem:</span>
              <span className="font-semibold text-slate-800">{passenger.origin}</span>
            </div>
            <div className="flex justify-between items-center text-slate-700">
              <span className="text-slate-500 font-medium">Destino:</span>
              <span className="font-semibold text-slate-800">{passenger.destination}</span>
            </div>
            <div className="flex justify-between items-center text-slate-700">
              <span className="text-slate-500 font-medium">Vendedor:</span>
              <span className="font-semibold text-slate-800">{passenger.seller}</span>
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-700 mb-2">
              Selecione o Motorista da Viagem:
            </label>

            {drivers.length === 0 ? (
              <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs text-amber-800 space-y-2">
                <p>Nenhum motorista cadastrado no momento.</p>
                <button
                  type="button"
                  onClick={() => {
                    onClose();
                    onOpenAddDriver();
                  }}
                  className="w-full py-2 bg-amber-600 hover:bg-amber-700 text-white font-semibold rounded-lg text-xs transition cursor-pointer"
                >
                  Cadastrar Motorista Agora
                </button>
              </div>
            ) : (
              <div className="space-y-1.5 max-h-56 overflow-y-auto pr-0.5">
                <button
                  type="button"
                  onClick={() => setSelectedDriverId('')}
                  className={`w-full text-left px-3 py-2.5 rounded-xl border text-xs font-medium flex items-center justify-between transition cursor-pointer ${
                    selectedDriverId === ''
                      ? 'border-amber-400 bg-amber-50 text-amber-900'
                      : 'border-slate-200 bg-white text-slate-700 hover:bg-slate-50'
                  }`}
                >
                  <span className="italic">Sem motorista alocado (Aguardando)</span>
                  {selectedDriverId === '' && <Check className="w-4 h-4 text-amber-600 shrink-0" />}
                </button>

                {drivers.map((driver) => {
                  const isSelected = selectedDriverId === driver.id;
                  return (
                    <button
                      key={driver.id}
                      type="button"
                      onClick={() => setSelectedDriverId(driver.id)}
                      className={`w-full text-left px-3 py-2.5 rounded-xl border text-xs font-semibold flex items-center justify-between transition cursor-pointer ${
                        isSelected
                          ? 'border-emerald-500 bg-emerald-50 text-emerald-900 shadow-2xs'
                          : 'border-slate-200 bg-white text-slate-800 hover:bg-slate-50'
                      }`}
                    >
                      <div className="flex items-center space-x-2 truncate mr-2">
                        <div
                          className={`w-6 h-6 rounded-md flex items-center justify-center shrink-0 ${
                            isSelected ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-600'
                          }`}
                        >
                          <Car className="w-3.5 h-3.5" />
                        </div>
                        <span className="truncate">{driver.fullName}</span>
                      </div>
                      {isSelected && <Check className="w-4 h-4 text-emerald-600 shrink-0" />}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="bg-slate-50 px-4 py-3 border-t border-slate-200 flex items-center justify-end space-x-2">
          <button
            type="button"
            onClick={onClose}
            className="px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-200 rounded-xl transition cursor-pointer"
          >
            Cancelar
          </button>
          <button
            type="button"
            onClick={handleSave}
            className="px-4 py-2 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl shadow-xs transition active:scale-95 cursor-pointer"
          >
            Confirmar Alocação
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/DriverManifestModal.tsx:
import React, { useState } from 'react';
import { X, Car, User, MapPin, Tag, Copy, Check, Share2, FileDown, UserMinus, RotateCcw } from 'lucide-react';
import { Driver, Passenger, CompanyConfig } from '../types';
import { generateDriverTripPdf } from '../utils/pdfGenerator';

interface DriverManifestModalProps {
  driver: Driver | null;
  passengers: Passenger[];
  isOpen: boolean;
  onClose: () => void;
  onUnallocatePassenger?: (passengerId: string) => void;
  onClearDriverPassengers?: (driverId: string) => void;
  companyConfig?: CompanyConfig;
}

export const DriverManifestModal: React.FC<DriverManifestModalProps> = ({
  driver,
  passengers,
  isOpen,
  onClose,
  onUnallocatePassenger,
  onClearDriverPassengers,
  companyConfig,
}) => {
  const [copied, setCopied] = useState(false);
  const [isConfirmingClear, setIsConfirmingClear] = useState(false);

  if (!isOpen || !driver) return null;

  const driverPassengers = passengers.filter((p) => p.driverId === driver.id);

  const generateManifestText = () => {
    let text = `🚐 *MANIFESTO DE EMBARQUE*\n`;
    text += `👤 *Motorista:* ${driver.fullName}\n`;
    text += `👥 *Total de Passageiros:* ${driverPassengers.length}\n`;
    text += `📅 *Data:* ${new Date().toLocaleDateString('pt-BR')}\n`;
    text += `-------------------------------\n`;

    if (driverPassengers.length === 0) {
      text += `Nenhum passageiro vinculado a esta viagem ainda.\n`;
    } else {
      driverPassengers.forEach((p, idx) => {
        text += `\n*${idx + 1}. ${p.fullName}*\n`;
        text += `   📍 Origem: ${p.origin}\n`;
        text += `   🏁 Destino: ${p.destination}\n`;
        text += `   🏷️ Vendedor: ${p.seller}\n`;
      });
    }

    return text;
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(generateManifestText());
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Falha ao copiar texto', err);
    }
  };

  const handleShareWhatsApp = () => {
    const text = generateManifestText();
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  const handleDownloadPdf = () => {
    generateDriverTripPdf(driver, passengers, companyConfig);
  };

  return (
    <div
      id="driver-manifest-backdrop"
      className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-3 sm:p-4"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        id="driver-manifest-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="manifest-title"
        className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-150 max-h-[90vh] flex flex-col"
      >
        {/* Modal Header */}
        <div className="bg-emerald-800 px-5 py-4 text-white flex items-center justify-between shrink-0">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-700 border border-emerald-500/30 flex items-center justify-center shadow-inner">
              <Car className="w-5 h-5 text-emerald-200" />
            </div>
            <div>
              <h2 id="manifest-title" className="font-bold text-base leading-tight">
                Manifesto de Viagem
              </h2>
              <p className="text-xs text-emerald-200 font-medium">
                Motorista: <span className="text-white font-bold">{driver.fullName}</span>
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-emerald-200 hover:text-white hover:bg-emerald-700/60 rounded-lg transition cursor-pointer"
            title="Fechar"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Action bar inside modal */}
        <div className="bg-slate-50 px-5 py-3 border-b border-slate-200 flex flex-wrap items-center justify-between gap-2 shrink-0">
          <div className="text-xs font-semibold text-slate-700">
            {driverPassengers.length} {driverPassengers.length === 1 ? 'passageiro' : 'passageiros'} nesta viagem
          </div>
          <div className="flex items-center space-x-1.5">
            <button
              onClick={handleDownloadPdf}
              className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-semibold bg-emerald-700 hover:bg-emerald-800 text-white rounded-lg shadow-2xs transition active:scale-95 cursor-pointer"
              title="Baixar em PDF oficial"
            >
              <FileDown className="w-3.5 h-3.5" />
              <span>PDF</span>
            </button>
            <button
              onClick={handleCopy}
              className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-semibold bg-white border border-slate-300 hover:bg-slate-100 text-slate-700 rounded-lg transition active:scale-95 cursor-pointer"
              title="Copiar lista para colar"
            >
              {copied ? (
                <>
                  <Check className="w-3.5 h-3.5 text-emerald-600" />
                  <span className="text-emerald-700">Copiado</span>
                </>
              ) : (
                <>
                  <Copy className="w-3.5 h-3.5" />
                  <span>Copiar</span>
                </>
              )}
            </button>
            <button
              onClick={handleShareWhatsApp}
              className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg shadow-2xs transition active:scale-95 cursor-pointer"
              title="Compartilhar no WhatsApp"
            >
              <Share2 className="w-3.5 h-3.5" />
              <span>WhatsApp</span>
            </button>
          </div>
        </div>

        {/* Passenger list */}
        <div className="p-4 sm:p-5 overflow-y-auto space-y-3 flex-1">
          {driverPassengers.length === 0 ? (
            <div className="text-center py-8 text-slate-500">
              <Car className="w-10 h-10 text-slate-300 mx-auto mb-2" />
              <p className="text-sm font-semibold text-slate-700">Nenhum passageiro vinculado</p>
              <p className="text-xs text-slate-400 mt-1 max-w-xs mx-auto">
                Na Lista Geral, aloque os passageiros para <strong>{driver.fullName}</strong> para que apareçam neste manifesto.
              </p>
            </div>
          ) : (
            driverPassengers.map((p, index) => (
              <div
                key={p.id}
                className="bg-slate-50 rounded-xl p-3 border border-slate-200/90 text-xs space-y-1.5"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-2">
                    <span className="w-5 h-5 rounded-full bg-emerald-700 text-white font-bold flex items-center justify-center text-[10px]">
                      {index + 1}
                    </span>
                    <span className="font-bold text-slate-900 text-sm">{p.fullName}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <span className="text-[11px] bg-amber-100/70 text-amber-900 px-2 py-0.5 rounded font-medium">
                      Vendedor: {p.seller}
                    </span>
                    {onUnallocatePassenger && (
                      <button
                        type="button"
                        onClick={() => onUnallocatePassenger(p.id)}
                        className="inline-flex items-center gap-1 text-[10px] text-rose-700 hover:text-rose-800 bg-rose-50 hover:bg-rose-100 border border-rose-200 px-2 py-0.5 rounded font-semibold cursor-pointer transition"
                        title="Retirar passageiro deste motorista (permanece seguro na Lista Geral)"
                      >
                        <UserMinus className="w-3 h-3" />
                        <span>Desalocar</span>
                      </button>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-2 pt-1 border-t border-slate-200/60 text-slate-600">
                  <div>
                    <span className="text-[10px] uppercase font-semibold text-slate-600 block">Origem:</span>
                    <span className="font-medium text-slate-800">{p.origin}</span>
                  </div>
                  <div>
                    <span className="text-[10px] uppercase font-semibold text-slate-600 block">Destino:</span>
                    <span className="font-medium text-slate-800">{p.destination}</span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Modal Footer */}
        <div className="bg-slate-50 px-5 py-3 border-t border-slate-200 flex flex-wrap items-center justify-between gap-2 shrink-0">
          <div className="flex items-center gap-2">
            {onClearDriverPassengers && driverPassengers.length > 0 && (
              isConfirmingClear ? (
                <div className="flex items-center gap-1.5 bg-amber-50 px-2.5 py-1 rounded-lg border border-amber-300">
                  <span className="text-[11px] font-semibold text-amber-900">Zerar passageiros deste motorista?</span>
                  <button
                    onClick={() => {
                      onClearDriverPassengers(driver.id);
                      setIsConfirmingClear(false);
                      onClose();
                    }}
                    className="px-2 py-0.5 bg-amber-600 hover:bg-amber-700 text-white text-[11px] font-bold rounded cursor-pointer transition"
                  >
                    Sim, Zerar
                  </button>
                  <button
                    onClick={() => setIsConfirmingClear(false)}
                    className="px-2 py-0.5 text-slate-600 hover:text-slate-800 text-[11px] font-medium cursor-pointer transition"
                  >
                    Cancelar
                  </button>
                </div>
              ) : (
                <button
                  onClick={() => setIsConfirmingClear(true)}
                  className="inline-flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-semibold text-amber-800 bg-amber-50 hover:bg-amber-100 border border-amber-200 rounded-lg transition active:scale-95 cursor-pointer"
                  title="Desvincular todos os passageiros deste motorista (permanecem salvos na Lista Geral e no histórico de Viagens)"
                >
                  <RotateCcw className="w-3.5 h-3.5 text-amber-600" />
                  <span>Zerar Passageiros</span>
                </button>
              )
            )}
            <p className="text-[11px] text-slate-500 italic hidden sm:block">
              * Desvincular passageiros mantém os dados salvos na Lista Geral e nas Viagens.
            </p>
          </div>
          <button
            onClick={onClose}
            className="px-4 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-200 rounded-lg transition cursor-pointer ml-auto"
          >
            Fechar
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/TripManager.tsx:
import React, { useState } from 'react';
import {
  Compass,
  Calendar,
  MapPin,
  Flag,
  Car,
  Users,
  PlusCircle,
  FileDown,
  Trash2,
  Edit3,
  Check,
  X,
  ArrowRight,
  UserCheck,
  UserPlus,
  AlertCircle,
  Info,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { Trip, Driver, Passenger, CompanyConfig } from '../types';
import { generateTripOfficialPdf } from '../utils/pdfGenerator';

interface TripManagerProps {
  trips: Trip[];
  drivers: Driver[];
  passengers: Passenger[];
  onSaveTrip: (trip: Trip) => void;
  onDeleteTrip: (tripId: string) => void;
  onOpenAddDriver: () => void;
  onNavigateToNewPassenger: () => void;
  companyConfig?: CompanyConfig;
}

export const TripManager: React.FC<TripManagerProps> = ({
  trips,
  drivers,
  passengers,
  onSaveTrip,
  onDeleteTrip,
  onOpenAddDriver,
  onNavigateToNewPassenger,
  companyConfig,
}) => {
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingTripId, setEditingTripId] = useState<string | null>(null);

  // Form fields
  const [date, setDate] = useState<string>(() => {
    const today = new Date();
    return today.toISOString().split('T')[0];
  });
  const [origin, setOrigin] = useState<string>('');
  const [destination, setDestination] = useState<string>('');
  const [selectedDriverId, setSelectedDriverId] = useState<string>('');
  const [selectedPassengerIds, setSelectedPassengerIds] = useState<string[]>([]);
  const [formError, setFormError] = useState<string | null>(null);

  const [tripToDelete, setTripToDelete] = useState<Trip | null>(null);
  const [expandedTripIds, setExpandedTripIds] = useState<Record<string, boolean>>({});

  // Filter passengers belonging to the currently selected driver or already part of the editing trip
  const driverPassengers = React.useMemo(() => {
    if (!selectedDriverId) return [];
    const editingTrip = trips.find((t) => t.id === editingTripId);
    return passengers.filter((p) => {
      if (p.driverId === selectedDriverId) return true;
      if (editingTrip && editingTrip.driverId === selectedDriverId && editingTrip.passengerIds?.includes(p.id)) {
        return true;
      }
      return false;
    });
  }, [passengers, selectedDriverId, editingTripId, trips]);

  const handleDriverChange = (driverId: string) => {
    setSelectedDriverId(driverId);
    if (!driverId) {
      setSelectedPassengerIds([]);
      return;
    }

    const assignedPassengerIds = passengers
      .filter((p) => p.driverId === driverId)
      .map((p) => p.id);

    setSelectedPassengerIds(assignedPassengerIds);
  };

  const handleOpenNewForm = () => {
    setEditingTripId(null);
    const today = new Date().toISOString().split('T')[0];
    setDate(today);

    const firstOrigin = passengers[0]?.origin || '';
    const firstDest = passengers[0]?.destination || '';
    setOrigin(firstOrigin);
    setDestination(firstDest);

    if (drivers.length > 0) {
      const defaultDriver = drivers[0].id;
      setSelectedDriverId(defaultDriver);
      const defaultPassengers = passengers
        .filter((p) => p.driverId === defaultDriver)
        .map((p) => p.id);
      setSelectedPassengerIds(defaultPassengers);
    } else {
      setSelectedDriverId('');
      setSelectedPassengerIds([]);
    }

    setFormError(null);
    setIsFormOpen(true);
  };

  const handleEditTrip = (trip: Trip) => {
    setEditingTripId(trip.id);
    setDate(trip.date);
    setOrigin(trip.origin);
    setDestination(trip.destination);
    setSelectedDriverId(trip.driverId);
    const validPassengerIds = (trip.passengerIds || []).filter((id) => {
      const p = passengers.find((pass) => pass.id === id);
      return p !== undefined;
    });
    setSelectedPassengerIds(validPassengerIds);
    setFormError(null);
    setIsFormOpen(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const togglePassengerSelection = (passengerId: string) => {
    setSelectedPassengerIds((prev) =>
      prev.includes(passengerId)
        ? prev.filter((id) => id !== passengerId)
        : [...prev, passengerId]
    );
  };

  const handleSelectAllDriverPassengers = () => {
    if (!selectedDriverId) return;
    const ids = passengers
      .filter((p) => p.driverId === selectedDriverId)
      .map((p) => p.id);
    setSelectedPassengerIds(ids);
  };

  const handleClearPassengerSelection = () => {
    setSelectedPassengerIds([]);
  };

  const toggleTripExpand = (tripId: string) => {
    setExpandedTripIds((prev) => ({
      ...prev,
      [tripId]: prev[tripId] === false ? true : false,
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!date.trim()) {
      setFormError('Informe a data da viagem.');
      return;
    }
    if (!origin.trim()) {
      setFormError('Informe a origem da viagem.');
      return;
    }
    if (!destination.trim()) {
      setFormError('Informe o destino da viagem.');
      return;
    }
    if (!selectedDriverId) {
      setFormError('Selecione o motorista desta viagem.');
      return;
    }

    const tripData: Trip = {
      id: editingTripId || `trip_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      date: date.trim(),
      origin: origin.trim().toUpperCase(),
      destination: destination.trim().toUpperCase(),
      driverId: selectedDriverId,
      passengerIds: selectedPassengerIds,
      createdAt: new Date().toISOString(),
    };

    onSaveTrip(tripData);
    setIsFormOpen(false);
  };

  const driverMap = React.useMemo(() => {
    const map = new Map<string, Driver>();
    drivers.forEach((d) => map.set(d.id, d));
    return map;
  }, [drivers]);

  const primaryColor = companyConfig?.primaryColor || '#065f46';

  return (
    <div className="space-y-6">
      {/* Title & Action Header */}
      <div className="bg-white p-4 sm:p-5 rounded-2xl border-2 border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h2 className="text-base sm:text-lg font-extrabold text-slate-900 flex items-center gap-2">
            <div
              className="w-8 h-8 rounded-xl flex items-center justify-center text-white shadow-2xs shrink-0"
              style={{ backgroundColor: primaryColor }}
            >
              <Compass className="w-4 h-4" />
            </div>
            <span>Guia de Viagens</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Planejamento de rotas, alocação de motoristas, lista de passageiros e emissão de relatórios oficiais em PDF com as cores da sua empresa.
          </p>
        </div>

        <button
          id="btn-new-trip"
          onClick={handleOpenNewForm}
          className="inline-flex items-center justify-center gap-1.5 px-4 py-2.5 text-white text-xs font-bold rounded-xl shadow-xs transition active:scale-95 cursor-pointer shrink-0"
          style={{ backgroundColor: primaryColor }}
        >
          <PlusCircle className="w-4 h-4" />
          <span>Programar Nova Viagem</span>
        </button>
      </div>

      {/* Creation / Editing Form Inline Box */}
      {isFormOpen && (
        <div className="bg-white rounded-2xl border-2 border-emerald-500 p-5 shadow-lg animate-in fade-in duration-200 space-y-4">
          <div className="flex items-center justify-between pb-3 border-b border-slate-200">
            <div className="flex items-center space-x-2.5">
              <div className="w-8 h-8 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center font-bold">
                <Compass className="w-4 h-4" />
              </div>
              <div>
                <h3 className="font-extrabold text-sm text-slate-900">
                  {editingTripId ? 'Alterar Dados da Viagem' : 'Programar Nova Viagem'}
                </h3>
                <p className="text-[11px] text-slate-500">
                  Preencha as informações para organizar a escala e os passageiros
                </p>
              </div>
            </div>
            <button
              onClick={() => setIsFormOpen(false)}
              className="p-1.5 text-slate-400 hover:text-slate-600 rounded-lg cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {formError && (
            <div className="p-3 bg-rose-50 border border-rose-200 rounded-xl text-xs text-rose-700 font-medium flex items-center gap-1.5">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{formError}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {/* Field: Data */}
              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">
                  Data da Viagem <span className="text-rose-500">*</span>
                </label>
                <div className="relative">
                  <Calendar className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                  <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    required
                    className="w-full pl-9 pr-3 py-2 text-xs bg-slate-50 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-emerald-600 font-bold text-slate-800"
                  />
                </div>
              </div>

              {/* Field 1: Cidade de Origem */}
              <div className="p-2.5 bg-emerald-50/30 rounded-xl border-2 border-emerald-200">
                <label className="flex items-center gap-1 text-xs font-bold text-emerald-950 mb-1">
                  <MapPin className="w-3.5 h-3.5 text-emerald-700" />
                  <span>Cidade de Origem <span className="text-rose-500">*</span></span>
                </label>
                <input
                  type="text"
                  value={origin}
                  onChange={(e) => setOrigin(e.target.value)}
                  placeholder="Ex: SÃO PAULO - SP"
                  required
                  className="w-full px-3 py-2 text-xs bg-white border-2 border-slate-300 rounded-xl focus:outline-none focus:border-emerald-600 font-bold text-slate-800 uppercase placeholder:normal-case placeholder:font-normal"
                />
              </div>

              {/* Field 2: Cidade de Destino */}
              <div className="p-2.5 bg-rose-50/30 rounded-xl border-2 border-rose-200">
                <label className="flex items-center gap-1 text-xs font-bold text-rose-950 mb-1">
                  <Flag className="w-3.5 h-3.5 text-rose-600" />
                  <span>Cidade de Destino <span className="text-rose-500">*</span></span>
                </label>
                <input
                  type="text"
                  value={destination}
                  onChange={(e) => setDestination(e.target.value)}
                  placeholder="Ex: RIO DE JANEIRO - RJ"
                  required
                  className="w-full px-3 py-2 text-xs bg-white border-2 border-slate-300 rounded-xl focus:outline-none focus:border-rose-600 font-bold text-slate-800 uppercase placeholder:normal-case placeholder:font-normal"
                />
              </div>
            </div>

            {/* Field: Motorista */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <label className="block text-xs font-bold text-slate-700">
                  Motorista Responsável <span className="text-rose-500">*</span>
                </label>
                <button
                  type="button"
                  onClick={onOpenAddDriver}
                  className="text-[11px] text-emerald-700 font-bold hover:underline cursor-pointer flex items-center gap-1"
                >
                  <PlusCircle className="w-3 h-3" />
                  <span>Cadastrar Novo Motorista</span>
                </button>
              </div>

              {drivers.length === 0 ? (
                <div className="p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs text-amber-800 flex items-center justify-between">
                  <span>Nenhum motorista cadastrado ainda. Cadastre um condutor primeiro.</span>
                  <button
                    type="button"
                    onClick={onOpenAddDriver}
                    className="font-bold underline ml-2 cursor-pointer"
                  >
                    + Cadastrar
                  </button>
                </div>
              ) : (
                <select
                  value={selectedDriverId}
                  onChange={(e) => handleDriverChange(e.target.value)}
                  required
                  className="w-full px-3 py-2 text-xs bg-slate-50 border-2 border-slate-200 rounded-xl focus:outline-none focus:border-emerald-600 font-bold text-slate-800 cursor-pointer"
                >
                  <option value="">-- Selecione o Motorista --</option>
                  {drivers.map((d) => (
                    <option key={d.id} value={d.id}>
                      {d.fullName} {d.phone ? `(${d.phone})` : ''}
                    </option>
                  ))}
                </select>
              )}
            </div>

            {/* Field: Seleção de Passageiros */}
            <div className="space-y-2 pt-2 border-t border-slate-200">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-1.5">
                <div>
                  <span className="block text-xs font-bold text-slate-800">
                    Passageiros desta Viagem ({selectedPassengerIds.length} selecionados)
                  </span>
                  <span className="text-[11px] text-slate-500">
                    Passageiros alocados para este motorista. Marque ou desmarque conforme a viagem:
                  </span>
                </div>

                {driverPassengers.length > 0 && (
                  <div className="flex items-center space-x-2 text-xs">
                    <button
                      type="button"
                      onClick={handleSelectAllDriverPassengers}
                      className="text-emerald-700 font-bold hover:underline cursor-pointer text-[11px]"
                    >
                      Marcar Todos ({driverPassengers.length})
                    </button>
                    <span className="text-slate-300">|</span>
                    <button
                      type="button"
                      onClick={handleClearPassengerSelection}
                      className="text-slate-500 font-medium hover:underline cursor-pointer text-[11px]"
                    >
                      Limpar
                    </button>
                  </div>
                )}
              </div>

              {driverPassengers.length === 0 ? (
                <div className="p-3.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-600 space-y-1.5">
                  <div className="flex items-center space-x-1.5 text-slate-700 font-bold">
                    <Info className="w-4 h-4 text-slate-500" />
                    <span>Nenhum passageiro atribuído a este motorista ainda</span>
                  </div>
                  <p className="text-[11px] text-slate-500">
                    Na <strong>Lista Geral</strong> ou na <strong>Lista do Dia</strong>, destine passageiros ao motorista escolhido ou cadastre um novo cliente.
                  </p>
                  <button
                    type="button"
                    onClick={onNavigateToNewPassenger}
                    className="inline-flex items-center gap-1 text-xs text-emerald-700 font-bold hover:underline cursor-pointer pt-1"
                  >
                    <PlusCircle className="w-3.5 h-3.5" />
                    <span>Cadastrar Novo Passageiro</span>
                  </button>
                </div>
              ) : (
                <div className="max-h-52 overflow-y-auto space-y-1.5 border-2 border-slate-200 rounded-xl p-2 bg-slate-50/60">
                  {driverPassengers.map((p) => {
                    const isSelected = selectedPassengerIds.includes(p.id);
                    return (
                      <label
                        key={p.id}
                        className={`flex items-center justify-between p-2 rounded-lg border-2 text-xs cursor-pointer transition ${
                          isSelected
                            ? 'bg-emerald-50 border-emerald-400 text-emerald-950 font-bold'
                            : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-50'
                        }`}
                      >
                        <div className="flex items-center space-x-2.5 min-w-0 pr-2">
                          <input
                            type="checkbox"
                            checked={isSelected}
                            onChange={() => togglePassengerSelection(p.id)}
                            className="w-4 h-4 text-emerald-600 rounded border-2 border-slate-300 focus:ring-emerald-500 cursor-pointer"
                          />
                          <div className="truncate">
                            <span className="block truncate font-bold text-slate-900">
                              {p.fullName}
                            </span>
                            <span className="text-[10px] text-slate-500 font-normal">
                              {p.origin} → {p.destination} • Vendedor: {p.seller}
                            </span>
                          </div>
                        </div>

                        <div className="shrink-0 flex items-center gap-1">
                          <span className="text-[10px] px-1.5 py-0.5 bg-emerald-100 text-emerald-800 font-bold rounded border border-emerald-300">
                            Do motorista
                          </span>
                        </div>
                      </label>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Form actions */}
            <div className="pt-3 border-t border-slate-200 flex items-center justify-end gap-2">
              <button
                type="button"
                onClick={() => setIsFormOpen(false)}
                className="px-3.5 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition cursor-pointer"
              >
                Cancelar
              </button>
              <button
                type="submit"
                className="px-5 py-2 text-xs font-bold text-white rounded-xl shadow-xs transition active:scale-95 cursor-pointer inline-flex items-center gap-1.5"
                style={{ backgroundColor: primaryColor }}
              >
                <Check className="w-4 h-4" />
                <span>{editingTripId ? 'Atualizar Viagem' : 'Salvar Viagem'}</span>
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Trips List with ENHANCED BORDERS & DISTINCT SEPARATION */}
      {trips.length === 0 && !isFormOpen ? (
        <div className="bg-white rounded-3xl border-2 border-slate-200 p-8 text-center shadow-xs">
          <div className="w-12 h-12 rounded-2xl bg-emerald-50 border border-emerald-200 flex items-center justify-center mx-auto mb-3 text-emerald-600">
            <Compass className="w-6 h-6" />
          </div>
          <h3 className="text-sm font-bold text-slate-800">
            Nenhuma viagem programada
          </h3>
          <p className="text-xs text-slate-500 mt-1 max-w-xs mx-auto mb-4">
            Crie sua primeira viagem definindo <strong>Data</strong>, <strong>Origem</strong>, <strong>Destino</strong> e <strong>Motorista</strong> para agrupar passageiros e emitir o relatório em PDF.
          </p>
          <button
            onClick={handleOpenNewForm}
            className="px-4 py-2 text-white text-xs font-semibold rounded-xl shadow-xs transition inline-flex items-center gap-1.5 cursor-pointer"
            style={{ backgroundColor: primaryColor }}
          >
            <PlusCircle className="w-4 h-4" />
            <span>Programar Primeira Viagem</span>
          </button>
        </div>
      ) : (
        <div className="space-y-6 sm:space-y-7">
          {trips.map((trip, index) => {
            const driver = driverMap.get(trip.driverId);
            const tripPassengers = passengers.filter((p) => trip.passengerIds.includes(p.id));
            const isExpanded = expandedTripIds[trip.id] !== false; // Default expanded

            // Format Brazilian date
            let displayDate = trip.date;
            if (trip.date && trip.date.includes('-')) {
              const parts = trip.date.split('-');
              if (parts.length === 3) {
                displayDate = `${parts[2]}/${parts[1]}/${parts[0]}`;
              }
            }

            const tripNumberStr = String(index + 1).padStart(2, '0');

            return (
              <div
                key={trip.id}
                className="bg-white rounded-3xl border-2 border-slate-300/90 hover:border-slate-400 shadow-sm hover:shadow-md transition-all duration-200 overflow-hidden relative"
              >
                {/* Trip Top Ribbon & Sequence Number */}
                <div className="bg-slate-50/90 px-4 sm:px-6 py-3.5 border-b-2 border-slate-200 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                  <div className="flex items-center space-x-3">
                    {/* Badge: Viagem #01 */}
                    <div className="flex items-center gap-1 px-2.5 py-1 rounded-xl bg-slate-900 text-white text-xs font-black tracking-wider shadow-2xs">
                      <span>VIAGEM #{tripNumberStr}</span>
                    </div>

