                              });
                            }}
                            className="w-24 px-2.5 py-1.5 text-xs font-bold border border-slate-300 rounded-lg text-slate-800 text-center pr-6 focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
                          />
                          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">
                            %
                          </span>
                        </div>

                        <button
                          type="button"
                          onClick={() => {
                            const val = parseFloat(tempInput);
                            handleSaveCommissionRate(sellerName, val);
                          }}
                          className="px-3 py-1.5 bg-emerald-700 hover:bg-emerald-800 text-white text-xs font-bold rounded-lg shadow-xs transition active:scale-95 cursor-pointer"
                        >
                          Salvar
                        </button>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      )}

      {/* MODAL DE CONFIGURAÇÃO FINANCEIRA GLOBAL */}
      {showConfigModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-xs p-4">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl border border-slate-200 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="px-5 py-4 bg-emerald-800 text-white flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Settings className="w-5 h-5 text-emerald-200" />
                <h3 className="text-sm sm:text-base font-extrabold">
                  Configurações Financeiras da Empresa
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setShowConfigModal(false)}
                className="text-white/80 hover:text-white text-lg font-bold p-1 cursor-pointer"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleSaveFinancialConfig} className="p-5 space-y-4">
              <p className="text-xs text-slate-500 leading-relaxed">
                Estes valores são utilizados para gerar com exatidão os balanços mensais, relatórios de faturamento e repasses da Osnir Turismo.
              </p>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700">
                  Valor Médio Padrão da Passagem (R$):
                </label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">
                    R$
                  </span>
                  <input
                    type="number"
                    min="0"
                    step="1"
                    required
                    value={financialConfig.ticketPrice}
                    onChange={(e) =>
                      setFinancialConfig({
                        ...financialConfig,
                        ticketPrice: parseFloat(e.target.value) || 0,
                      })
                    }
                    className="w-full pl-9 pr-3 py-2 text-xs sm:text-sm font-semibold border border-slate-300 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
                  />
                </div>
                <span className="text-[10px] text-slate-400">
                  Valor cobrado por passageiro para cálculo do faturamento bruto.
                </span>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700">
                  Valor Padrão Repassado por Viagem ao Motorista (R$):
                </label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">
                    R$
                  </span>
                  <input
                    type="number"
                    min="0"
                    step="1"
                    required
                    value={financialConfig.driverTripPrice}
                    onChange={(e) =>
                      setFinancialConfig({
                        ...financialConfig,
                        driverTripPrice: parseFloat(e.target.value) || 0,
                      })
                    }
                    className="w-full pl-9 pr-3 py-2 text-xs sm:text-sm font-semibold border border-slate-300 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
                  />
                </div>
                <span className="text-[10px] text-slate-400">
                  Diária ou valor fixo pago ao motorista por viagem realizada.
                </span>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700">
                  Porcentagem Padrão de Comissão do Vendedor (%):
                </label>
                <div className="relative">
                  <input
                    type="number"
                    min="0"
                    max="100"
                    step="0.5"
                    required
                    value={financialConfig.defaultCommissionPercent}
                    onChange={(e) =>
                      setFinancialConfig({
                        ...financialConfig,
                        defaultCommissionPercent: parseFloat(e.target.value) || 0,
                      })
                    }
                    className="w-full pl-3 pr-8 py-2 text-xs sm:text-sm font-semibold border border-slate-300 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500"
                  />
                  <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">
                    %
                  </span>
                </div>
                <span className="text-[10px] text-slate-400">
                  Taxa aplicada aos vendedores que não tiverem comissão personalizada.
                </span>
              </div>

              <div className="pt-3 border-t border-slate-100 flex items-center justify-end space-x-2">
                <button
                  type="button"
                  onClick={() => setShowConfigModal(false)}
                  className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold rounded-xl transition cursor-pointer"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-emerald-700 hover:bg-emerald-800 text-white text-xs font-bold rounded-xl shadow-xs transition cursor-pointer"
                >
                  Salvar Configurações
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/SettingsManager.tsx:
import React, { useState, useRef } from 'react';
import {
  Settings,
  Building2,
  Image as ImageIcon,
  Palette,
  Upload,
  Trash2,
  AlertTriangle,
  Download,
  Database,
  Users,
  Car,
  Compass,
  CalendarDays,
  CheckCircle2,
  ShieldAlert,
  Info,
  X,
  FileCheck,
  RotateCcw,
  Sparkles,
  Phone,
  FileText,
  Save,
  Eye,
} from 'lucide-react';
import { Passenger, Driver, Trip, FinancialConfig, CompanyConfig } from '../types';
import { getAllDataExport, DEFAULT_COMPANY_CONFIG } from '../utils/storage';
import { KeyRound, ShieldCheck, FolderArchive, Loader2 } from 'lucide-react';
import JSZip from 'jszip';
import projectFilesBundle from '../projectFilesBundle.json';

interface SettingsManagerProps {
  passengers: Passenger[];
  drivers: Driver[];
  trips: Trip[];
  dailyLists: Record<string, string[]>;
  financialConfig: FinancialConfig;
  companyConfig: CompanyConfig;
  onSaveCompanyConfig: (config: CompanyConfig) => void;
  onClearAllData: (resetFinancial: boolean) => void;
  onOpenLicenseModal?: () => void;
  onOpenDatabaseModal?: () => void;
}

const COLOR_PRESETS = [
  {
    name: 'Esmeralda Turismo (Padrão)',
    primary: '#065f46',
    secondary: '#047857',
    accent: '#10b981',
  },
  {
    name: 'Azul Real Executivo',
    primary: '#1e3a8a',
    secondary: '#1d4ed8',
    accent: '#38bdf8',
  },
  {
    name: 'Vinho Nobre & Ouro',
    primary: '#831843',
    secondary: '#9d174d',
    accent: '#f59e0b',
  },
  {
    name: 'Grafite Executivo',
    primary: '#0f172a',
    secondary: '#334155',
    accent: '#64748b',
  },
  {
    name: 'Terracota Transporte',
    primary: '#9a3412',
    secondary: '#c2410c',
    accent: '#ea580c',
  },
  {
    name: 'Marrom & Âmbar Elegance',
    primary: '#78350f',
    secondary: '#92400e',
    accent: '#d97706',
  },
];

export const SettingsManager: React.FC<SettingsManagerProps> = ({
  passengers,
  drivers,
  trips,
  dailyLists,
  financialConfig,
  companyConfig,
  onSaveCompanyConfig,
  onClearAllData,
  onOpenLicenseModal,
  onOpenDatabaseModal,
}) => {
  // Company configuration form state
  const [companyName, setCompanyName] = useState(companyConfig?.companyName || 'Osnir Turismo');
  const [logoUrl, setLogoUrl] = useState(companyConfig?.logoUrl || '');
  const [primaryColor, setPrimaryColor] = useState(companyConfig?.primaryColor || '#065f46');
  const [secondaryColor, setSecondaryColor] = useState(companyConfig?.secondaryColor || '#047857');
  const [accentColor, setAccentColor] = useState(companyConfig?.accentColor || '#10b981');
  const [phone, setPhone] = useState(companyConfig?.phone || '');
  const [cnpjOrCpf, setCnpjOrCpf] = useState(companyConfig?.cnpjOrCpf || '');

  // Clear data confirmation modal state
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [confirmationWord, setConfirmationWord] = useState('');
  const [resetFinancial, setResetFinancial] = useState(false);
  const [feedbackToast, setFeedbackToast] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const dailyDatesCount = Object.keys(dailyLists).filter(
    (k) => Array.isArray(dailyLists[k]) && dailyLists[k].length > 0
  ).length;

  const showFeedback = (msg: string) => {
    setFeedbackToast(msg);
    setTimeout(() => setFeedbackToast(null), 3500);
  };

  // Handle Logo Upload from Local File
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      showFeedback('Por favor, selecione um arquivo de imagem válido (PNG, JPG, WEBP ou SVG).');
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64 = event.target?.result as string;
      setLogoUrl(base64);
      showFeedback('Logomarca carregada com sucesso! Clique em "Salvar Configurações" para gravar.');
    };
    reader.onerror = () => {
      showFeedback('Falha ao ler o arquivo de imagem.');
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveLogo = () => {
    setLogoUrl('');
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    showFeedback('Logomarca removida. Clique em "Salvar Configurações" para confirmar.');
  };

  const handleApplyPreset = (preset: typeof COLOR_PRESETS[0]) => {
    setPrimaryColor(preset.primary);
    setSecondaryColor(preset.secondary);
    setAccentColor(preset.accent);
    showFeedback(`Paleta "${preset.name}" selecionada! Clique em salvar.`);
  };

  const handleSaveAllCompanyConfig = (e: React.FormEvent) => {
    e.preventDefault();

    const trimmedName = companyName.trim() || 'Osnir Turismo';
    const newConfig: CompanyConfig = {
      companyName: trimmedName,
      logoUrl: logoUrl.trim(),
      primaryColor: primaryColor.trim() || '#065f46',
      secondaryColor: secondaryColor.trim() || '#047857',
      accentColor: accentColor.trim() || '#10b981',
      phone: phone.trim(),
      cnpjOrCpf: cnpjOrCpf.trim(),
    };

    onSaveCompanyConfig(newConfig);
    showFeedback('Configurações salvas! Nome, logomarca e cores aplicados ao app e a todos os PDFs.');
  };

  const handleRestoreDefaultBranding = () => {
    setCompanyName(DEFAULT_COMPANY_CONFIG.companyName);
    setLogoUrl(DEFAULT_COMPANY_CONFIG.logoUrl);
    setPrimaryColor(DEFAULT_COMPANY_CONFIG.primaryColor);
    setSecondaryColor(DEFAULT_COMPANY_CONFIG.secondaryColor);
    setAccentColor(DEFAULT_COMPANY_CONFIG.accentColor || '#10b981');
    setPhone(DEFAULT_COMPANY_CONFIG.phone || '');
    setCnpjOrCpf(DEFAULT_COMPANY_CONFIG.cnpjOrCpf || '');

    onSaveCompanyConfig(DEFAULT_COMPANY_CONFIG);
    showFeedback('Configurações visuais restauradas para os padrões originais!');
  };

  const [isGeneratingZip, setIsGeneratingZip] = useState(false);

  const handleDownloadProjectZipDirectly = async () => {
    try {
      setIsGeneratingZip(true);
      showFeedback('Gerando arquivo ZIP com todos os arquivos do instalador...');

      const zip = new JSZip();
      const filesMap = projectFilesBundle as Record<string, string>;

      for (const [filePath, fileContent] of Object.entries(filesMap)) {
        if (filePath.endsWith('.png')) {
          zip.file(filePath, fileContent, { base64: true });
        } else {
          zip.file(filePath, fileContent);
        }
      }

      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const downloadAnchor = document.createElement('a');
      downloadAnchor.href = url;
      downloadAnchor.download = 'OSNIR_TURISMO_SISTEMA_COMPLETO.zip';
      document.body.appendChild(downloadAnchor);
      downloadAnchor.click();
      downloadAnchor.remove();
      URL.revokeObjectURL(url);

      showFeedback('Arquivo ZIP baixado com sucesso direto no seu computador!');
    } catch (error) {
      console.error('Erro ao gerar ZIP local:', error);
      showFeedback('Houve um problema ao gerar o ZIP. Tente novamente.');
    } finally {
      setIsGeneratingZip(false);
    }
  };

  const handleExportBackup = () => {
    try {
      const data = getAllDataExport();
      const jsonString = `data:text/json;charset=utf-8,${encodeURIComponent(JSON.stringify(data, null, 2))}`;
      const downloadAnchor = document.createElement('a');
      downloadAnchor.setAttribute('href', jsonString);
      const today = new Date().toISOString().substring(0, 10);
      const safeName = (companyName || 'transporte').toLowerCase().replace(/\s+/g, '_');
      downloadAnchor.setAttribute('download', `backup_${safeName}_${today}.json`);
      document.body.appendChild(downloadAnchor);
      downloadAnchor.click();
      downloadAnchor.remove();

      showFeedback('Backup completo de todos os dados baixado com sucesso!');
    } catch (error) {
      console.error('Erro ao gerar backup', error);
      showFeedback('Não foi possível gerar o arquivo de backup.');
    }
  };

  const handleOpenModal = () => {
    setConfirmationWord('');
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setConfirmationWord('');
  };

  const isConfirmedValid = confirmationWord.trim().toUpperCase() === 'ZERAR';

  const handleExecuteClearAll = () => {
    if (!isConfirmedValid) return;
    onClearAllData(resetFinancial);
    handleCloseModal();
    showFeedback('Todos os dados foram zerados com sucesso!');
  };

  return (
    <div className="space-y-6 pb-8">
      {/* Toast Feedback */}
      {feedbackToast && (
        <div className="fixed top-4 inset-x-0 z-50 flex justify-center pointer-events-none px-4">
          <div className="bg-slate-900 text-white text-xs font-semibold py-2.5 px-4 rounded-xl shadow-2xl flex items-center space-x-2 animate-in fade-in slide-in-from-top-4 duration-200">
            <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
            <span>{feedbackToast}</span>
          </div>
        </div>
      )}

      {/* Main Header Banner */}
      <div className="bg-white p-4 sm:p-5 rounded-2xl border-2 border-slate-200 shadow-xs">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div className="flex items-start gap-3">
            <div
              className="w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-xs shrink-0"
              style={{ backgroundColor: primaryColor }}
            >
              <Settings className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base sm:text-lg font-extrabold text-slate-900 tracking-tight">
                  Configuração do Aplicativo & Identidade Visual
                </h2>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-md bg-slate-100 text-slate-700 border border-slate-200 uppercase">
                  Personalização
                </span>
              </div>
              <p className="text-xs text-slate-500 mt-1">
                Cadastre o nome da empresa, logomarca oficial e as cores personalizadas que serão aplicadas no aplicativo e em todas as guias emitidas em PDF.
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2 shrink-0">
            {onOpenDatabaseModal && (
              <button
                type="button"
                id="btn-settings-database"
                onClick={onOpenDatabaseModal}
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-blue-50 hover:bg-blue-100 text-blue-700 text-xs font-bold rounded-xl border border-blue-200 transition active:scale-95 cursor-pointer"
                title="Status do banco de dados local"
              >
                <Database className="w-3.5 h-3.5" />
                <span>Banco de Dados</span>
              </button>
            )}

            {onOpenLicenseModal && (
              <button
                type="button"
                id="btn-settings-license"
                onClick={onOpenLicenseModal}
                className="inline-flex items-center gap-1.5 px-3 py-2 bg-amber-50 hover:bg-amber-100 text-amber-900 text-xs font-bold rounded-xl border border-amber-300 transition active:scale-95 cursor-pointer"
                title="Gerenciar Chave de Produto e Instalações"
              >
                <KeyRound className="w-3.5 h-3.5 text-amber-600" />
                <span>Chave do Produto (3 PCs)</span>
              </button>
            )}

            <button
              type="button"
              id="btn-download-project-zip-top"
              onClick={handleDownloadProjectZipDirectly}
              disabled={isGeneratingZip}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl shadow-xs transition active:scale-95 cursor-pointer disabled:opacity-50"
              title="Baixar pacote ZIP completo com arquivos e o gerador de instalador .exe"
            >
              {isGeneratingZip ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <FolderArchive className="w-3.5 h-3.5 text-white" />
              )}
              <span>{isGeneratingZip ? 'Gerando ZIP...' : 'Baixar ZIP do Projeto'}</span>
            </button>

            <button
              type="button"
              id="btn-export-backup-top"
              onClick={handleExportBackup}
              className="inline-flex items-center gap-1.5 px-3.5 py-2 bg-slate-800 hover:bg-slate-900 text-white text-xs font-bold rounded-xl shadow-xs transition active:scale-95 cursor-pointer"
              title="Exportar backup completo de todos os dados"
            >
              <Download className="w-3.5 h-3.5 text-slate-300" />
              <span>Fazer Backup (JSON)</span>
            </button>
          </div>
        </div>
      </div>

      {/* CARD DESTAQUE: SOFTWARE INSTALADOR DESKTOP & LICENCIAMENTO */}
      <div className="bg-gradient-to-br from-slate-900 via-slate-850 to-slate-900 text-white rounded-2xl p-5 border border-slate-700 shadow-md">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center space-x-2">
              <span className="px-2 py-0.5 rounded-md bg-amber-500/20 text-amber-300 text-[10px] font-extrabold uppercase tracking-wider border border-amber-500/30">
                Software Instalador Desktop Windows (.exe / .msi)
              </span>
              <span className="px-2 py-0.5 rounded-md bg-emerald-500/20 text-emerald-300 text-[10px] font-extrabold uppercase tracking-wider border border-emerald-500/30">
                1 Chave = Até 3 Computadores
              </span>
            </div>
            <h3 className="text-base sm:text-lg font-bold text-white">
              Pronto para Venda Comercial e Instalação em Agências
            </h3>
            <p className="text-xs text-slate-300 max-w-2xl leading-relaxed">
              O sistema foi configurado com <strong>Tauri</strong> para gerar um instalador clássico ultra leve (5 a 10 MB). Na primeira execução na máquina do cliente, o <strong>banco de dados local é criado e inicializado automaticamente</strong>, e a ativação garante o limite de 3 computadores por chave.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2.5 shrink-0">
            <button
              type="button"
              id="btn-download-installer-bundle-card"
              onClick={handleDownloadProjectZipDirectly}
              disabled={isGeneratingZip}
              className="py-2.5 px-4 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-slate-950 font-black text-xs transition shadow-sm flex items-center space-x-2 cursor-pointer disabled:opacity-50"
              title="Baixar ZIP completo do projeto para gerar o instalador"
            >
              {isGeneratingZip ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <FolderArchive className="w-4 h-4" />
              )}
              <span>{isGeneratingZip ? 'Preparando...' : 'Baixar ZIP para Instalador'}</span>
            </button>

            {onOpenLicenseModal && (
              <button
                type="button"
                onClick={onOpenLicenseModal}
                className="py-2.5 px-4 rounded-xl bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-slate-950 font-black text-xs transition shadow-sm flex items-center space-x-2 cursor-pointer"
              >
                <KeyRound className="w-4 h-4" />
                <span>Gerenciar Licença & Gerar Chaves</span>
              </button>
            )}

            {onOpenDatabaseModal && (
              <button
                type="button"
                onClick={onOpenDatabaseModal}
                className="py-2.5 px-3.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 font-bold text-xs transition border border-slate-600 flex items-center space-x-2 cursor-pointer"
              >
                <Database className="w-4 h-4 text-blue-400" />
                <span>Status do Banco</span>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* SEÇÃO 1: CADASTRO DA EMPRESA, LOGOMARCA E CORES */}
      <form
        onSubmit={handleSaveAllCompanyConfig}
        className="bg-white rounded-2xl border-2 border-slate-200 shadow-xs overflow-hidden"
      >
        {/* Form Title Strip */}
        <div className="px-5 py-4 bg-slate-50/80 border-b border-slate-200 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div className="flex items-center space-x-2.5">
            <div className="w-8 h-8 rounded-lg bg-emerald-100 text-emerald-800 flex items-center justify-center font-bold">
              <Building2 className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-extrabold text-slate-900">
                1. Dados da Empresa & Identidade Visual
              </h3>
              <p className="text-[11px] text-slate-500">
                Essas informações aparecem no cabeçalho do sistema e em todos os relatórios impressos
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleRestoreDefaultBranding}
              className="inline-flex items-center gap-1 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold rounded-lg transition border border-slate-200 cursor-pointer"
              title="Restaurar nome e cores padrão do sistema"
            >
              <RotateCcw className="w-3 h-3 text-slate-500" />
              <span>Restaurar Padrão</span>
            </button>

            <button
              type="submit"
              id="btn-save-company-config"
              className="inline-flex items-center gap-1.5 px-4 py-1.5 text-white text-xs font-bold rounded-lg shadow-xs transition active:scale-95 cursor-pointer"
              style={{ backgroundColor: primaryColor }}
            >
              <Save className="w-3.5 h-3.5" />
              <span>Salvar Alterações</span>
            </button>
          </div>
        </div>

        <div className="p-5 sm:p-6 space-y-6">
          {/* Row 1: Nome da Empresa, Telefone e CNPJ */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="sm:col-span-1 space-y-1.5">
