                <div className="text-[11px] text-slate-700 leading-tight">
                  <span className="font-bold block text-slate-800">Redefinir também valores e comissões</span>
                  Restaura o preço da passagem (R$ 120), diária do motorista (R$ 350) e comissões para o padrão.
                </div>
              </label>

              {/* Security Verification Input */}
              <div className="space-y-2 pt-1">
                <label className="block font-extrabold text-slate-800 text-xs">
                  Para confirmar, digite a palavra <span className="text-rose-700 uppercase font-black bg-rose-100 px-1.5 py-0.5 rounded">ZERAR</span> abaixo:
                </label>
                <input
                  type="text"
                  id="input-confirm-clear-all"
                  value={confirmationWord}
                  onChange={(e) => setConfirmationWord(e.target.value)}
                  placeholder="Digite ZERAR para desbloquear o botão"
                  autoFocus
                  className="w-full px-3 py-2 text-xs sm:text-sm bg-white border border-slate-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-rose-500 focus:border-rose-500 font-bold uppercase placeholder:normal-case placeholder:font-normal text-rose-900"
                />
                {!isConfirmedValid && confirmationWord.length > 0 && (
                  <p className="text-[11px] text-rose-600 font-medium">
                    A palavra digitada deve ser exatamente ZERAR.
                  </p>
                )}
              </div>
            </div>

            {/* Modal Footer */}
            <div className="px-5 py-3.5 bg-slate-50 border-t border-slate-200 flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={handleCloseModal}
                className="px-3.5 py-2 text-xs font-bold text-slate-700 hover:bg-slate-200 rounded-xl transition cursor-pointer"
              >
                Cancelar e Manter Dados
              </button>

              <button
                type="button"
                id="btn-confirm-clear-all-final"
                onClick={handleExecuteClearAll}
                disabled={!isConfirmedValid}
                className={`inline-flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-extrabold transition cursor-pointer ${
                  isConfirmedValid
                    ? 'bg-rose-600 hover:bg-rose-700 text-white shadow-xs active:scale-95'
                    : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                }`}
                title={isConfirmedValid ? 'Zerar todos os dados agora' : 'Digite ZERAR para habilitar'}
              >
                <Trash2 className="w-3.5 h-3.5" />
                <span>Sim, Zerar Tudo Definitivamente</span>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

src/components/LicenseModal.tsx:
import React, { useState, useEffect } from 'react';
import {
  ShieldCheck,
  KeyRound,
  Laptop,
  CheckCircle2,
  AlertTriangle,
  X,
  Copy,
  Check,
  Sparkles,
  Download,
  Trash2,
  HelpCircle,
} from 'lucide-react';
import {
  getMachineFingerprint,
  validateProductKey,
  activateProduct,
  getStoredLicense,
  isProductActivated,
  getTrialStatus,
  revokeLicense,
  exportLicenseCertificate,
} from '../utils/license';
import { ProductLicense } from '../types';
import { AdminLicenseGenerator } from './AdminLicenseGenerator';

interface LicenseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLicenseUpdated?: (license: ProductLicense | null) => void;
}

export const LicenseModal: React.FC<LicenseModalProps> = ({
  isOpen,
  onClose,
  onLicenseUpdated,
}) => {
  const [activeLicense, setActiveLicense] = useState<ProductLicense | null>(null);
  const [machineId, setMachineId] = useState<string>('');
  const [inputKey, setInputKey] = useState<string>('');
  const [clientName, setClientName] = useState<string>('');
  const [slotNumber, setSlotNumber] = useState<1 | 2 | 3>(1);
  const [machineLabel, setMachineLabel] = useState<string>('');
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [successMessage, setSuccessMessage] = useState<string>('');
  const [showAdminGenerator, setShowAdminGenerator] = useState<boolean>(false);
  const [copiedId, setCopiedId] = useState<boolean>(false);

  const trialStatus = getTrialStatus();

  useEffect(() => {
    if (isOpen) {
      const lic = getStoredLicense();
      setActiveLicense(lic);
      const hwid = getMachineFingerprint();
      setMachineId(hwid);
      setErrorMessage('');
      setSuccessMessage('');
      if (lic) {
        setClientName(lic.licenseeName);
        setInputKey(lic.productKey);
        setSlotNumber(lic.currentSlot);
      }
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleCopyMachineId = () => {
    navigator.clipboard.writeText(machineId);
    setCopiedId(true);
    setTimeout(() => setCopiedId(false), 2500);
  };

  const handleActivate = () => {
    setErrorMessage('');
    setSuccessMessage('');

    if (!inputKey.trim()) {
      setErrorMessage('Por favor, informe a chave de produto.');
      return;
    }

    const validation = validateProductKey(inputKey);
    if (!validation.valid) {
      setErrorMessage(validation.message);
      return;
    }

    const result = activateProduct(
      inputKey,
      clientName || 'Empresa Licenciada',
      slotNumber,
      machineLabel || `Computador Instalação #${slotNumber}`
    );

    if (result.success && result.license) {
      setActiveLicense(result.license);
      setSuccessMessage(result.message);
      if (onLicenseUpdated) onLicenseUpdated(result.license);
    } else {
      setErrorMessage(result.message);
    }
  };

  const handleRevoke = () => {
    if (window.confirm('Tem certeza que deseja desvincular a licença deste computador? Esta máquina voltará a ficar bloqueada até ser inserida uma nova chave.')) {
      revokeLicense();
      setActiveLicense(null);
      setInputKey('');
      setSuccessMessage('Licença desvinculada com sucesso desta máquina.');
      if (onLicenseUpdated) onLicenseUpdated(null);
    }
  };

  const handleApplyGeneratedKey = (key: string, name: string) => {
    setInputKey(key);
    setClientName(name);
    setShowAdminGenerator(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in overflow-y-auto">
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl border border-slate-200 overflow-hidden my-6">
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 text-white p-5 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-2xl bg-amber-500/20 border border-amber-400/30 flex items-center justify-center text-amber-400">
              <ShieldCheck className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-lg font-extrabold text-white flex items-center gap-2">
                Licença do Sistema
                {activeLicense ? (
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                    Ativado (1 de {activeLicense.maxInstallations} Instalações)
                  </span>
                ) : trialStatus.isTrialActive ? (
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30">
                    Avaliação: {trialStatus.daysRemaining} dias restantes
                  </span>
                ) : (
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-rose-500/20 text-rose-300 border border-rose-500/30">
                    Não Ativado
                  </span>
                )}
              </h2>
              <p className="text-xs text-slate-300">
                Gerenciamento de Chave de Produto e Máquinas Autorizadas
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-9 h-9 rounded-xl bg-white/10 hover:bg-white/20 text-white flex items-center justify-center transition cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-6">
          {/* Identificador da Máquina */}
          <div className="bg-slate-50 p-3.5 rounded-2xl border border-slate-200 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
            <div className="flex items-center space-x-2.5">
              <Laptop className="w-5 h-5 text-slate-500 shrink-0" />
              <div>
                <span className="text-[11px] font-bold text-slate-500 uppercase tracking-wider block">
                  Código desta Máquina (Hardware ID):
                </span>
                <code className="text-xs font-mono font-extrabold text-slate-800">
                  {machineId}
                </code>
              </div>
            </div>
            <button
              onClick={handleCopyMachineId}
              className="px-3 py-1.5 rounded-xl bg-white hover:bg-slate-100 text-slate-700 text-xs font-bold border border-slate-300 transition flex items-center justify-center space-x-1 cursor-pointer self-start sm:self-auto"
            >
              {copiedId ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
              <span>{copiedId ? 'Copiado!' : 'Copiar ID'}</span>
            </button>
          </div>

          {/* Se o produto já estiver ativado */}
          {activeLicense ? (
            <div className="bg-emerald-50/70 rounded-2xl p-5 border border-emerald-200 space-y-4">
              <div className="flex items-start space-x-3">
                <CheckCircle2 className="w-6 h-6 text-emerald-600 shrink-0 mt-0.5" />
                <div className="space-y-1">
                  <h4 className="text-base font-bold text-emerald-950">
                    Software Licenciado & Liberado!
                  </h4>
                  <p className="text-xs text-emerald-800">
                    Licença vinculada com sucesso a este computador e autorizada para uso comercial.
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs pt-1">
                <div className="bg-white p-3 rounded-xl border border-emerald-100 shadow-2xs">
                  <span className="text-slate-400 block text-[10px] font-semibold">EMPRESA LICENCIADA:</span>
                  <span className="text-slate-900 font-extrabold text-sm">{activeLicense.licenseeName}</span>
                </div>

                <div className="bg-white p-3 rounded-xl border border-emerald-100 shadow-2xs">
                  <span className="text-slate-400 block text-[10px] font-semibold">SLOT DE INSTALAÇÃO:</span>
                  <span className="text-emerald-700 font-extrabold text-sm">
                    Máquina {activeLicense.currentSlot} de {activeLicense.maxInstallations} Computadores
                  </span>
                </div>

                <div className="bg-white p-3 rounded-xl border border-emerald-100 shadow-2xs">
                  <span className="text-slate-400 block text-[10px] font-semibold">TIPO DE PLANO:</span>
                  <span className="text-slate-800 font-bold">
                    {activeLicense.planType === 'lifetime' ? 'Vitalícia (Sem mensalidades)' : 'Anual'}
                  </span>
                </div>

                <div className="bg-white p-3 rounded-xl border border-emerald-100 shadow-2xs">
                  <span className="text-slate-400 block text-[10px] font-semibold">CHAVE DO PRODUTO:</span>
                  <span className="font-mono font-extrabold text-slate-800">
                    {activeLicense.productKey}
                  </span>
                </div>
              </div>

              <div className="flex flex-wrap gap-2 pt-2">
                <button
                  onClick={exportLicenseCertificate}
                  className="py-2 px-3 rounded-xl bg-white hover:bg-slate-100 text-slate-800 text-xs font-bold border border-slate-300 transition flex items-center space-x-1.5 cursor-pointer shadow-2xs"
                >
                  <Download className="w-3.5 h-3.5" />
                  <span>Baixar Certificado (.json)</span>
                </button>

                <button
                  onClick={handleRevoke}
                  className="py-2 px-3 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-700 text-xs font-bold border border-rose-200 transition flex items-center space-x-1.5 cursor-pointer"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                  <span>Desvincular deste Computador</span>
                </button>
              </div>
            </div>
          ) : (
            /* Formulário de Ativação */
            <div className="space-y-4">
              <div className="bg-amber-50/80 p-4 rounded-2xl border border-amber-200 text-xs text-amber-900 space-y-1">
                <div className="font-bold flex items-center gap-1.5 text-amber-950">
                  <KeyRound className="w-4 h-4 text-amber-700" />
                  Ativação de 3 Instalações por Chave
                </div>
                <p>
                  Insira a chave fornecida na compra. Você pode usar a <strong>mesma chave em até 3 computadores</strong> da sua empresa (ex: Computador 1 no escritório, Computador 2 na agência e Computador 3 no guichê).
                </p>
              </div>

              <div className="space-y-3">
                <div>
                  <label className="text-xs font-bold text-slate-700 block mb-1">
                    Chave do Produto (Product Key):
                  </label>
                  <div className="relative">
                    <input
                      type="text"
                      value={inputKey}
                      onChange={(e) => setInputKey(e.target.value.toUpperCase())}
                      placeholder="OT26-XXXX-YYYY-ZZZZ-3S"
                      className="w-full pl-10 pr-4 py-2.5 rounded-xl border-2 border-slate-300 focus:border-amber-500 focus:ring-2 focus:ring-amber-200 text-base font-mono font-bold text-slate-900 placeholder:text-slate-400 placeholder:font-normal"
                    />
                    <KeyRound className="w-5 h-5 text-slate-400 absolute left-3 top-3" />
                  </div>
                  <span className="text-[11px] text-slate-400 mt-1 block">
                    Formato oficial: OT26-XXXX-YYYY-ZZZZ-3S (ou teste rápido: <strong className="text-slate-600">OT26-DEMO-TEST-2026-3S</strong>)
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-bold text-slate-700 block mb-1">
                      Nome da Empresa Compradora:
                    </label>
                    <input
                      type="text"
                      value={clientName}
                      onChange={(e) => setClientName(e.target.value)}
                      placeholder="Ex: OSNIR TURISMO"
                      className="w-full px-3 py-2 rounded-xl border border-slate-300 focus:border-amber-500 text-sm font-semibold text-slate-900"
                    />
                  </div>

                  <div>
                    <label className="text-xs font-bold text-slate-700 block mb-1">
                      Qual computador é este? (1 a 3):
                    </label>
                    <select
                      value={slotNumber}
                      onChange={(e) => setSlotNumber(parseInt(e.target.value) as 1 | 2 | 3)}
                      className="w-full px-3 py-2 rounded-xl border border-slate-300 focus:border-amber-500 text-sm font-semibold text-slate-900 bg-white"
                    >
                      <option value={1}>Computador 1 de 3 (Principal / Servidor)</option>
                      <option value={2}>Computador 2 de 3 (Agência / Vendas)</option>
                      <option value={3}>Computador 3 de 3 (Guichê / Financeiro)</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="text-xs font-bold text-slate-700 block mb-1">
                    Identificação desta Máquina (Opcional):
                  </label>
                  <input
                    type="text"
                    value={machineLabel}
                    onChange={(e) => setMachineLabel(e.target.value)}
                    placeholder="Ex: Notebook da Recepção"
                    className="w-full px-3 py-2 rounded-xl border border-slate-300 focus:border-amber-500 text-sm text-slate-900"
                  />
                </div>
              </div>

              {errorMessage && (
                <div className="p-3 bg-rose-50 border border-rose-200 text-rose-700 rounded-xl text-xs font-semibold flex items-center gap-2">
                  <AlertTriangle className="w-4 h-4 shrink-0" />
                  <span>{errorMessage}</span>
                </div>
              )}

              {successMessage && (
                <div className="p-3 bg-emerald-50 border border-emerald-200 text-emerald-800 rounded-xl text-xs font-semibold flex items-center gap-2">
                  <CheckCircle2 className="w-4 h-4 shrink-0" />
                  <span>{successMessage}</span>
                </div>
              )}

              <button
                onClick={handleActivate}
                className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-slate-950 font-black text-sm shadow-md transition flex items-center justify-center space-x-2 cursor-pointer"
              >
                <ShieldCheck className="w-5 h-5" />
                <span>ATIVAR PRODUTO NESTE COMPUTADOR</span>
              </button>
            </div>
          )}

          {/* Seção do Desenvolvedor / Vendedor (Gerador de Chaves) */}
          <div className="pt-2 border-t border-slate-200">
            <button
              onClick={() => setShowAdminGenerator(!showAdminGenerator)}
              className="w-full py-2 px-3 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold flex items-center justify-between transition cursor-pointer"
            >
              <span className="flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-amber-600" />
                {showAdminGenerator ? 'Ocultar Gerador de Chaves do Vendedor' : 'Ferramenta do Vendedor: Gerar Chave para Novo Cliente'}
              </span>
              <span className="text-[10px] text-slate-500 uppercase font-extrabold bg-slate-200 px-2 py-0.5 rounded">
                Admin
              </span>
            </button>

            {showAdminGenerator && (
              <div className="mt-3">
                <AdminLicenseGenerator onApplyKey={handleApplyGeneratedKey} />
              </div>
            )}
          </div>
        </div>

        <div className="bg-slate-50 px-6 py-3 border-t border-slate-200 flex items-center justify-between text-xs text-slate-500">
          <span>Sistema OSNIR TURISMO • Licenciamento V2.5</span>
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold transition cursor-pointer"
          >
            Fechar
          </button>
        </div>
      </div>
    </div>
  );
};

src/components/DatabaseStatusModal.tsx:
import React, { useState, useEffect } from 'react';
import {
  Database,
  HardDrive,
  Download,
  Upload,
  RefreshCw,
  CheckCircle2,
  AlertTriangle,
  X,
  ShieldCheck,
  FileJson,
  Layers,
  Sparkles,
} from 'lucide-react';
import {
  getDatabaseStatistics,
  exportDatabaseBackupFile,
  restoreDatabaseFromFile,
  initializeLocalDatabase,
} from '../utils/database';

interface DatabaseStatusModalProps {
  isOpen: boolean;
  onClose: () => void;
  onDataRestored?: () => void;
}

export const DatabaseStatusModal: React.FC<DatabaseStatusModalProps> = ({
  isOpen,
  onClose,
  onDataRestored,
}) => {
  const [stats, setStats] = useState(getDatabaseStatistics());
  const [statusMessage, setStatusMessage] = useState<string>('');
  const [isError, setIsError] = useState<boolean>(false);

  useEffect(() => {
    if (isOpen) {
      setStats(getDatabaseStatistics());
      setStatusMessage('');
      setIsError(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleBackup = () => {
    try {
      exportDatabaseBackupFile();
      setStatusMessage('Arquivo de backup do banco de dados gerado e baixado com sucesso!');
      setIsError(false);
      setStats(getDatabaseStatistics());
    } catch {
      setStatusMessage('Falha ao gerar arquivo de backup.');
      setIsError(true);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      if (!content) return;
      const res = restoreDatabaseFromFile(content);
      if (res.success) {
        setStatusMessage(res.message);
        setIsError(false);
        setStats(getDatabaseStatistics());
        if (onDataRestored) onDataRestored();
      } else {
        setStatusMessage(res.message);
        setIsError(true);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleReinit = () => {
    if (
      window.confirm(
        'ATENÇÃO: Deseja reinicializar o banco de dados? Isso recriará a estrutura padrão do sistema. Recomendamos fazer um backup antes!'
      )
    ) {
      const res = initializeLocalDatabase();
      setStatusMessage(`Banco reinicializado: ${res.message}`);
      setIsError(false);
      setStats(getDatabaseStatistics());
      if (onDataRestored) onDataRestored();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-fade-in overflow-y-auto">
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl border border-slate-200 overflow-hidden my-6">
        {/* Header */}
        <div className="bg-gradient-to-r from-slate-900 to-slate-800 text-white p-5 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-2xl bg-blue-500/20 border border-blue-400/30 flex items-center justify-center text-blue-400">
              <Database className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-lg font-extrabold text-white flex items-center gap-2">
                Banco de Dados Local
                <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                  Status: Saudável / Ativo
                </span>
              </h2>
              <p className="text-xs text-slate-300">
                Criado automaticamente na instalação • Armazenamento isolado no computador
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="w-9 h-9 rounded-xl bg-white/10 hover:bg-white/20 text-white flex items-center justify-center transition cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-6">
          {/* Informações Técnicas do Banco */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
            <div className="bg-slate-50 p-3 rounded-xl border border-slate-200">
              <span className="text-slate-400 block text-[10px] font-bold uppercase">ID da Instância:</span>
              <span className="text-slate-900 font-extrabold font-mono text-xs truncate block">
                {stats.metadata.databaseId}
              </span>
            </div>

            <div className="bg-slate-50 p-3 rounded-xl border border-slate-200">
              <span className="text-slate-400 block text-[10px] font-bold uppercase">Versão do Schema:</span>
              <span className="text-slate-900 font-bold text-xs">{stats.metadata.version}</span>
            </div>

            <div className="bg-slate-50 p-3 rounded-xl border border-slate-200">
              <span className="text-slate-400 block text-[10px] font-bold uppercase">Espaço Ocupado:</span>
              <span className="text-blue-700 font-extrabold text-xs">{stats.storageSizeFormatted}</span>
            </div>

            <div className="bg-slate-50 p-3 rounded-xl border border-slate-200">
              <span className="text-slate-400 block text-[10px] font-bold uppercase">Total Registros:</span>
              <span className="text-emerald-700 font-extrabold text-xs">{stats.counts.totalRecords} itens</span>
            </div>
          </div>

          {/* Contagem por Tabela */}
          <div className="bg-slate-50/80 p-4 rounded-2xl border border-slate-200 space-y-2">
            <div className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
              <Layers className="w-4 h-4 text-slate-500" />
              Tabelas e Registros Criados na Instalação:
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2.5 text-xs pt-1">
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Passageiros:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.passengers}
                </span>
              </div>
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Viagens:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.trips}
                </span>
              </div>
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Motoristas:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.drivers}
                </span>
              </div>
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Despesas:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.expenses}
                </span>
              </div>
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Tarifas / Destinos:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.destinations}
                </span>
              </div>
              <div className="bg-white p-2.5 rounded-lg border border-slate-200 flex justify-between items-center">
                <span className="text-slate-600 font-medium">Fechamentos:</span>
                <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">
                  {stats.counts.tripClosings}
                </span>
              </div>
            </div>
          </div>

          {/* Mensagens de Feedback */}
          {statusMessage && (
            <div
              className={`p-3 rounded-xl text-xs font-semibold flex items-center gap-2 ${
                isError
                  ? 'bg-rose-50 border border-rose-200 text-rose-700'
                  : 'bg-emerald-50 border border-emerald-200 text-emerald-800'
              }`}
            >
              {isError ? <AlertTriangle className="w-4 h-4 shrink-0" /> : <CheckCircle2 className="w-4 h-4 shrink-0" />}
              <span>{statusMessage}</span>
            </div>
          )}

          {/* Ações de Backup e Restauração */}
          <div className="space-y-3 pt-1">
            <h4 className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
              <HardDrive className="w-4 h-4 text-slate-500" />
              Rotinas de Segurança & Backup
            </h4>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <button
                onClick={handleBackup}
                className="p-3.5 rounded-xl border-2 border-slate-200 hover:border-blue-500 hover:bg-blue-50/40 transition flex items-center space-x-3 text-left cursor-pointer group"
              >
                <div className="w-10 h-10 rounded-xl bg-blue-100 text-blue-700 flex items-center justify-center shrink-0 group-hover:scale-105 transition">
                  <Download className="w-5 h-5" />
                </div>
                <div>
                  <span className="font-extrabold text-sm text-slate-800 block">Fazer Backup Agora</span>
                  <span className="text-[11px] text-slate-500 block">
                    Exporta arquivo .json completo com todos os dados para pen drive ou nuvem
                  </span>
                </div>
              </button>

              <label className="p-3.5 rounded-xl border-2 border-slate-200 hover:border-emerald-500 hover:bg-emerald-50/40 transition flex items-center space-x-3 text-left cursor-pointer group">
                <div className="w-10 h-10 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center shrink-0 group-hover:scale-105 transition">
                  <Upload className="w-5 h-5" />
                </div>
                <div>
                  <span className="font-extrabold text-sm text-slate-800 block">Restaurar Backup</span>
                  <span className="text-[11px] text-slate-500 block">
                    Importa arquivo de backup (.json) para recuperar os dados nesta máquina
                  </span>
                </div>
                <input
                  type="file"
                  accept=".json"
                  onChange={handleFileUpload}
                  className="hidden"
                />
              </label>
            </div>
          </div>

          <div className="pt-2 border-t border-slate-200 flex items-center justify-between">
            <button
              onClick={handleReinit}
              className="text-xs text-slate-500 hover:text-slate-800 flex items-center gap-1 cursor-pointer font-medium"
            >
              <RefreshCw className="w-3 h-3" />
              <span>Verificar integridade / Reinicializar tabelas</span>
            </button>
            <span className="text-[10px] text-slate-400">
              Última validação: {new Date().toLocaleDateString('pt-BR')}
            </span>
          </div>
        </div>

        <div className="bg-slate-50 px-6 py-3 border-t border-slate-200 flex items-center justify-between text-xs text-slate-500">
          <span>Banco de Dados Local OSNIR TURISMO</span>
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded-xl bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold transition cursor-pointer"
          >
            Fechar
          </button>
        </div>
      </div>
    </div>
  );
};

